INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$02527f43$SATQ$, $SATQ$727ad47c-2691-4500-8350-2815c043093a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>&ldquo;Raymond&rsquo;s Run&rdquo; is a short story.</li>
<li>It was written by African American author Toni Cade Bambara.</li>
<li>It was first published in her book <em>Gorilla, My Love</em> in 1972.</li>
<li>It is told from a first person perspective.</li>
<li>It takes place in Harlem.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to indicate where the short story takes place. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"91b6acd1-138a-408b-bed4-092349286733","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; takes place in Harlem.</p>"},{"id":"7ae532c8-f896-4f5b-a3d0-617c2c46d671","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; was published in <em>Gorilla, My Love</em>.</p>"},{"id":"2b98eab3-b7f4-4f9a-a968-72844bf6a342","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; is told from a first person perspective.</p>"},{"id":"84bed345-cf5f-4f00-8f12-1c30568e2744","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; was written by Toni Cade Bambara.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["91b6acd1-138a-408b-bed4-092349286733"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence indicates where "Raymond&rsquo;s Run" takes place, stating that it takes place in Harlem.</p><p>Choice B is incorrect. The sentence identifies the book in which the story "Raymond&rsquo;s Run" was published; it doesn&rsquo;t indicate where the story takes place. Choice C is incorrect. The sentence indicates the point of view used in "Raymond&rsquo;s Run"; it doesn&rsquo;t indicate where the story takes place. Choice D is incorrect. The sentence identifies the author of "Raymond&rsquo;s Run"; it doesn&rsquo;t indicate where the story takes place.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"02527f43","external_id":"727ad47c-2691-4500-8350-2815c043093a","vaultid":null,"uId":"f52bcf5e-2889-454c-80e1-fae70de4c991","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>&ldquo;Raymond&rsquo;s Run&rdquo; is a short story.</li>\n<li>It was written by African American author Toni Cade Bambara.</li>\n<li>It was first published in her book <em>Gorilla, My Love</em> in 1972.</li>\n<li>It is told from a first person perspective.</li>\n<li>It takes place in Harlem.</li>\n</ul>","stem":"<p>The student wants to indicate where the short story takes place. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"91b6acd1-138a-408b-bed4-092349286733","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; takes place in Harlem.</p>"},{"id":"7ae532c8-f896-4f5b-a3d0-617c2c46d671","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; was published in <em>Gorilla, My Love</em>.</p>"},{"id":"2b98eab3-b7f4-4f9a-a968-72844bf6a342","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; is told from a first person perspective.</p>"},{"id":"84bed345-cf5f-4f00-8f12-1c30568e2744","content":"<p>&ldquo;Raymond&rsquo;s Run&rdquo; was written by Toni Cade Bambara.</p>"}],"keys":["91b6acd1-138a-408b-bed4-092349286733"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence indicates where \"Raymond&rsquo;s Run\" takes place, stating that it takes place in Harlem.</p><p>Choice B is incorrect. The sentence identifies the book in which the story \"Raymond&rsquo;s Run\" was published; it doesn&rsquo;t indicate where the story takes place. Choice C is incorrect. The sentence indicates the point of view used in \"Raymond&rsquo;s Run\"; it doesn&rsquo;t indicate where the story takes place. Choice D is incorrect. The sentence identifies the author of \"Raymond&rsquo;s Run\"; it doesn&rsquo;t indicate where the story takes place.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669208,"updateDate":1743430669208}$SATQ$::jsonb, 1743430669208, 1743430669208),
    ($SATQ$04397a63$SATQ$, $SATQ$b0070e01-03e6-4c54-846c-6a22403d3c3b$SATQ$::uuid, $SATQ$4f29c058-efb7-4e59-bd03-cdfabf4618ff$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The Haudenosaunee Confederacy is a nearly 1,000-year-old alliance of six Native nations in the northeastern US.  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</li>
<li>The members are bound by a centuries-old agreement known as the Great Law of Peace.</li>
<li>Historian Bruce Johansen is one of several scholars who believe that the principles of the Great Law of Peace influenced the US Constitution.</li>
<li>This theory is called the influence theory.</li>
<li>Johansen cites the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to present the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"bb7d79c8-2d01-4447-bafb-1bccdb221cb9","content":"<p>Historian Bruce Johansen believes that the Great Law of Peace was very influential.</p>"},{"id":"fc0bd0f3-7d1f-4413-9256-5ea20794d3f9","content":"<p>The influence theory is supported by the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy.</p>"},{"id":"b5a38d01-4730-4555-bbc6-0b3894ccd946","content":"<p>The influence theory holds that the principles of the Great Law of Peace, a centuries-old agreement binding six Native nations in the northeastern US, influenced the US Constitution.</p>"},{"id":"a937cd66-1964-42a2-850e-5d2b7a1ba033","content":"<p>Native people, including the members of the Haudenosaunee Confederacy, influenced the founding of the US in many different ways.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b5a38d01-4730-4555-bbc6-0b3894ccd946"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence effectively presents the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy, explaining the theory&rsquo;s position that the Great Law of Peace influenced the US Constitution while avoiding mention of the Haudenosaunee Confederacy itself. </p><p>Choice A is incorrect. The sentence broadly emphasizes Johansen&rsquo;s ideas about the Great Law of Peace; it doesn&rsquo;t identify the influence theory or effectively present it. Choice B is incorrect. The sentence emphasizes one fact that supports the influence theory; it doesn&rsquo;t effectively present the theory to an audience unfamiliar with the Haudenosaunee Confederacy. Choice D is incorrect. The sentence makes a broad generalization about Native people&rsquo;s influence on the founding of the US; it doesn&rsquo;t effectively present the influence theory. </p>$SATQ$, false, 0, $SATQ$OSP-728-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$ece2a7bf-740a-4965-ab79-ca35c0c9ace7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"04397a63","external_id":"b0070e01-03e6-4c54-846c-6a22403d3c3b","vaultid":"4f29c058-efb7-4e59-bd03-cdfabf4618ff","uId":"85341849-165e-49e3-b77f-7c0b9cf3d96d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The Haudenosaunee Confederacy is a nearly 1,000-year-old alliance of six Native nations in the northeastern US.  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</li>\n<li>The members are bound by a centuries-old agreement known as the Great Law of Peace.</li>\n<li>Historian Bruce Johansen is one of several scholars who believe that the principles of the Great Law of Peace influenced the US Constitution.</li>\n<li>This theory is called the influence theory.</li>\n<li>Johansen cites the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy.</li>\n</ul>","stem":"<p>The student wants to present the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"bb7d79c8-2d01-4447-bafb-1bccdb221cb9","content":"<p>Historian Bruce Johansen believes that the Great Law of Peace was very influential.</p>"},{"id":"fc0bd0f3-7d1f-4413-9256-5ea20794d3f9","content":"<p>The influence theory is supported by the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy.</p>"},{"id":"b5a38d01-4730-4555-bbc6-0b3894ccd946","content":"<p>The influence theory holds that the principles of the Great Law of Peace, a centuries-old agreement binding six Native nations in the northeastern US, influenced the US Constitution.</p>"},{"id":"a937cd66-1964-42a2-850e-5d2b7a1ba033","content":"<p>Native people, including the members of the Haudenosaunee Confederacy, influenced the founding of the US in many different ways.</p>"}],"keys":["b5a38d01-4730-4555-bbc6-0b3894ccd946"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence effectively presents the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy, explaining the theory&rsquo;s position that the Great Law of Peace influenced the US Constitution while avoiding mention of the Haudenosaunee Confederacy itself. </p><p>Choice A is incorrect. The sentence broadly emphasizes Johansen&rsquo;s ideas about the Great Law of Peace; it doesn&rsquo;t identify the influence theory or effectively present it. Choice B is incorrect. The sentence emphasizes one fact that supports the influence theory; it doesn&rsquo;t effectively present the theory to an audience unfamiliar with the Haudenosaunee Confederacy. Choice D is incorrect. The sentence makes a broad generalization about Native people&rsquo;s influence on the founding of the US; it doesn&rsquo;t effectively present the influence theory. </p>","parenttemplatename":"OSP-728-SYN","parenttemplateid":"","templateclusterid":"ece2a7bf-740a-4965-ab79-ca35c0c9ace7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349),
    ($SATQ$04ad68ca$SATQ$, $SATQ$c490a6f2-5032-4f04-a7d8-655c68bad279$SATQ$::uuid, $SATQ$3dca2189-e56a-4b79-a9b5-5f2f12af8931$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In Gothic architecture, flying buttresses are large arches that help support a building&rsquo;s exterior walls. Before the Gothic era, cathedrals&rsquo; heavy ceilings had to be supported by thick, short walls, but the invention of flying buttresses eliminated this need. <span aria-hidden="true">______</span><span class="sr-only">blank</span> Gothic cathedrals could be built with thinner, higher walls.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"097c1f9b-733e-4ffc-bc5f-9933ef3b76fd","content":"<p>Similarly,</p>"},{"id":"adbd7a46-4582-49c1-95dd-d97bc9d86060","content":"<p>For instance,</p>"},{"id":"fbbc5b02-9500-436f-a7b0-46bbbf72b2df","content":"<p>Nevertheless,</p>"},{"id":"a0caf447-92e7-44d1-9ecf-e753795a2246","content":"<p>As a result,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["a0caf447-92e7-44d1-9ecf-e753795a2246"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;As a result&rdquo; logically signals that the thinner, higher walls in this sentence were a result of the invention of flying buttresses in the previous sentence. </p><p>Choice A is incorrect because &ldquo;similarly&rdquo; illogically signals that the thinner, higher walls in this sentence are similar to the invention of flying buttresses in the previous sentence. Instead, the walls were a result of that invention. Choice B is incorrect because &ldquo;for instance&rdquo; illogically signals that the thinner, higher walls in this sentence are an example supporting the statement about the invention of flying buttresses in the previous sentence. Instead, the walls were a result of that invention. Choice C is incorrect because &ldquo;nevertheless&rdquo; illogically signals that the thinner, higher walls in this sentence occurred despite the invention of flying buttresses in the previous sentence. Instead, the walls were a result of that invention. </p>$SATQ$, false, 0, $SATQ$OSP-248-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$e3c6f316-0cdc-4d70-bd42-ea98fffe73e8$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"04ad68ca","external_id":"c490a6f2-5032-4f04-a7d8-655c68bad279","vaultid":"3dca2189-e56a-4b79-a9b5-5f2f12af8931","uId":"253c82e2-9203-4e3a-bdff-6a3fe16ee9f7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In Gothic architecture, flying buttresses are large arches that help support a building&rsquo;s exterior walls. Before the Gothic era, cathedrals&rsquo; heavy ceilings had to be supported by thick, short walls, but the invention of flying buttresses eliminated this need. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Gothic cathedrals could be built with thinner, higher walls.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"097c1f9b-733e-4ffc-bc5f-9933ef3b76fd","content":"<p>Similarly,</p>"},{"id":"adbd7a46-4582-49c1-95dd-d97bc9d86060","content":"<p>For instance,</p>"},{"id":"fbbc5b02-9500-436f-a7b0-46bbbf72b2df","content":"<p>Nevertheless,</p>"},{"id":"a0caf447-92e7-44d1-9ecf-e753795a2246","content":"<p>As a result,</p>"}],"keys":["a0caf447-92e7-44d1-9ecf-e753795a2246"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;As a result&rdquo; logically signals that the thinner, higher walls in this sentence were a result of the invention of flying buttresses in the previous sentence. </p><p>Choice A is incorrect because &ldquo;similarly&rdquo; illogically signals that the thinner, higher walls in this sentence are similar to the invention of flying buttresses in the previous sentence. Instead, the walls were a result of that invention. Choice B is incorrect because &ldquo;for instance&rdquo; illogically signals that the thinner, higher walls in this sentence are an example supporting the statement about the invention of flying buttresses in the previous sentence. Instead, the walls were a result of that invention. Choice C is incorrect because &ldquo;nevertheless&rdquo; illogically signals that the thinner, higher walls in this sentence occurred despite the invention of flying buttresses in the previous sentence. Instead, the walls were a result of that invention. </p>","parenttemplatename":"OSP-248-TRA","parenttemplateid":"","templateclusterid":"e3c6f316-0cdc-4d70-bd42-ea98fffe73e8","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$064c8999$SATQ$, $SATQ$50489abb-3e1a-4a09-b2c3-a28606fec2ce$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The Haber-Bosch process is an industrial process used to manufacture ammonia (NH<sub>3</sub>).</li>
<li>It was invented by chemists Fritz Haber and Carl Bosch in 1910.</li>
<li>The process&rsquo;s primary reaction combines nitrogen (N<sub>2</sub>) from the air with hydrogen (H<sub>2</sub>).</li>
<li>It requires an iron catalyst and high temperatures and pressures.</li>
<li>Most of the ammonia produced by this process is used in fertilizers.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to provide an overview of the Haber-Bosch process. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"97609345-9257-466d-9167-ecab8337aff4","content":"<p>The Haber-Bosch process needs nitrogen, hydrogen, and an iron catalyst.</p>"},{"id":"3b6bf913-e9c8-4ed8-bc45-199360d74676","content":"<p>The Haber-Bosch process uses an iron catalyst along with high temperatures and pressures to manufacture ammonia from nitrogen and hydrogen.</p>"},{"id":"31e309e1-84cf-4799-b9f0-fe3ff993e555","content":"<p>Chemists Fritz Haber and Carl Bosch invented an industrial process to manufacture ammonia to be used in fertilizers.</p>"},{"id":"10a5045c-7769-45a2-aa1b-b194f1f62240","content":"<p>In 1910, chemists Fritz Haber and Carl Bosch invented the Haber-Bosch process, which requires high temperatures and pressures.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["3b6bf913-e9c8-4ed8-bc45-199360d74676"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence provides an overview of the Haber-Bosch process, explaining that it uses an iron catalyst, high temperatures, and high pressures to manufacture ammonia from nitrogen and hydrogen.</p><p>Choice A is incorrect. While the sentence identifies some of the process&rsquo;s required components (nitrogen, hydrogen, and an iron catalyst), the overview is incomplete; it doesn&rsquo;t explain what the process does (produces ammonia) or mention the conditions needed for it to function (high temperatures and pressures). Choice C is incorrect. While the sentence indicates who invented the process (Fritz Haber and Carl Bosch) and that it produces ammonia, the overview is incomplete; it doesn&rsquo;t mention any of the necessary ingredients or conditions. Choice D is incorrect. While the sentence mentions the inventors of the process along with the required conditions (high temperatures and pressures), it doesn&rsquo;t explain that the process produces ammonia or indicate what components are needed.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"064c8999","external_id":"50489abb-3e1a-4a09-b2c3-a28606fec2ce","vaultid":null,"uId":"07907946-5359-4876-a1e4-6de46aef1088","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The Haber-Bosch process is an industrial process used to manufacture ammonia (NH<sub>3</sub>).</li>\n<li>It was invented by chemists Fritz Haber and Carl Bosch in 1910.</li>\n<li>The process&rsquo;s primary reaction combines nitrogen (N<sub>2</sub>) from the air with hydrogen (H<sub>2</sub>).</li>\n<li>It requires an iron catalyst and high temperatures and pressures.</li>\n<li>Most of the ammonia produced by this process is used in fertilizers.</li>\n</ul>","stem":"<p>The student wants to provide an overview of the Haber-Bosch process. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"97609345-9257-466d-9167-ecab8337aff4","content":"<p>The Haber-Bosch process needs nitrogen, hydrogen, and an iron catalyst.</p>"},{"id":"3b6bf913-e9c8-4ed8-bc45-199360d74676","content":"<p>The Haber-Bosch process uses an iron catalyst along with high temperatures and pressures to manufacture ammonia from nitrogen and hydrogen.</p>"},{"id":"31e309e1-84cf-4799-b9f0-fe3ff993e555","content":"<p>Chemists Fritz Haber and Carl Bosch invented an industrial process to manufacture ammonia to be used in fertilizers.</p>"},{"id":"10a5045c-7769-45a2-aa1b-b194f1f62240","content":"<p>In 1910, chemists Fritz Haber and Carl Bosch invented the Haber-Bosch process, which requires high temperatures and pressures.</p>"}],"keys":["3b6bf913-e9c8-4ed8-bc45-199360d74676"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence provides an overview of the Haber-Bosch process, explaining that it uses an iron catalyst, high temperatures, and high pressures to manufacture ammonia from nitrogen and hydrogen.</p><p>Choice A is incorrect. While the sentence identifies some of the process&rsquo;s required components (nitrogen, hydrogen, and an iron catalyst), the overview is incomplete; it doesn&rsquo;t explain what the process does (produces ammonia) or mention the conditions needed for it to function (high temperatures and pressures). Choice C is incorrect. While the sentence indicates who invented the process (Fritz Haber and Carl Bosch) and that it produces ammonia, the overview is incomplete; it doesn&rsquo;t mention any of the necessary ingredients or conditions. Choice D is incorrect. While the sentence mentions the inventors of the process along with the required conditions (high temperatures and pressures), it doesn&rsquo;t explain that the process produces ammonia or indicate what components are needed.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$072666a3$SATQ$, $SATQ$52042590-ec3e-4ea6-b3a3-db7869ee35b7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The tiny transistors that control the flow of electricity in modern devices may one day be made of wood. Researchers in Switzerland have found a way to use heat and chemicals to widen the grooves in dry pieces of balsa wood. <span aria-hidden="true">______</span><span class="sr-only">blank</span> these grooves become wide enough that electrical conductors can be passed through them.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"ec4db86b-f7ba-413a-b38c-440fbe0b2155","content":"<p>For example,</p>"},{"id":"94fb86ab-5a28-4b28-9be6-9f9ba84de62f","content":"<p>Previously,</p>"},{"id":"475b31ce-1fef-411d-a6b7-12b77428d479","content":"<p>In contrast,</p>"},{"id":"9f865b27-ea6c-4482-8c7c-8c2e26d02763","content":"<p>As a result,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["9f865b27-ea6c-4482-8c7c-8c2e26d02763"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;As a result&rdquo; logically signals that the information in this sentence&mdash;that the widened grooves in balsa wood can accommodate electrical conductors&mdash;is a direct consequence of the researchers&rsquo; method described in the previous sentence (using heat and chemicals to widen the grooves).</p><p>Choice A is incorrect because &ldquo;for example&rdquo; illogically signals that this sentence provides an example of the researchers&rsquo; method described in the previous sentence. Instead, the sentence indicates a consequence of that method. Choice B is incorrect because &ldquo;previously&rdquo; illogically signals that this sentence describes an event that occurred before the researchers&rsquo; development of the method described in the previous sentence. Instead, the sentence indicates a consequence of that method. Choice C is incorrect because &ldquo;in contrast&rdquo; illogically signals that the information in this sentence contrasts with the previous sentence&rsquo;s description of the researchers&rsquo; method. Instead, the sentence indicates a consequence of that method.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"072666a3","external_id":"52042590-ec3e-4ea6-b3a3-db7869ee35b7","vaultid":null,"uId":"9908f3ac-df68-4c27-8923-055b0fe2ea0e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The tiny transistors that control the flow of electricity in modern devices may one day be made of wood. Researchers in Switzerland have found a way to use heat and chemicals to widen the grooves in dry pieces of balsa wood. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> these grooves become wide enough that electrical conductors can be passed through them.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"ec4db86b-f7ba-413a-b38c-440fbe0b2155","content":"<p>For example,</p>"},{"id":"94fb86ab-5a28-4b28-9be6-9f9ba84de62f","content":"<p>Previously,</p>"},{"id":"475b31ce-1fef-411d-a6b7-12b77428d479","content":"<p>In contrast,</p>"},{"id":"9f865b27-ea6c-4482-8c7c-8c2e26d02763","content":"<p>As a result,</p>"}],"keys":["9f865b27-ea6c-4482-8c7c-8c2e26d02763"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;As a result&rdquo; logically signals that the information in this sentence&mdash;that the widened grooves in balsa wood can accommodate electrical conductors&mdash;is a direct consequence of the researchers&rsquo; method described in the previous sentence (using heat and chemicals to widen the grooves).</p><p>Choice A is incorrect because &ldquo;for example&rdquo; illogically signals that this sentence provides an example of the researchers&rsquo; method described in the previous sentence. Instead, the sentence indicates a consequence of that method. Choice B is incorrect because &ldquo;previously&rdquo; illogically signals that this sentence describes an event that occurred before the researchers&rsquo; development of the method described in the previous sentence. Instead, the sentence indicates a consequence of that method. Choice C is incorrect because &ldquo;in contrast&rdquo; illogically signals that the information in this sentence contrasts with the previous sentence&rsquo;s description of the researchers&rsquo; method. Instead, the sentence indicates a consequence of that method.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$07456405$SATQ$, $SATQ$38a5c95b-f2c6-4f5c-95c4-9054cd57ded1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li><span> </span><span>Malapportionment is the over- or underrepresentation (relative to population size) of electoral districts in a governing body.</span></li>
<li><span>It is a common feature of representative governments.</span></li>
<li>There are 169 seats in Norway&rsquo;s supreme legislature (the Storting).</li>
<li>Seats are distributed by a formula that awards 1 point per resident and 1.8 points per unit of land.</li>
<li>Less populated rural districts with large tracts of land receive a disproportionate number of seats compared to smaller but more populated urban districts.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to refute a claim that malapportionment in the Storting favors small urban districts. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"5c33f4cf-fbdc-4b50-9298-45f8bc1986ae","content":"<p>Less populated rural districts are disproportionally underrepresented in the Storting, creating an unfair advantage for smaller but more populated urban districts.&nbsp;</p>"},{"id":"22a28d2a-6254-40e1-b824-d70e520801e5","content":"<p>It&rsquo;s untrue that malapportionment in the 169-seat Storting favors small urban districts; rather, the formula for distributing seats overrepresents more populated districts.</p>"},{"id":"37e84bce-22ab-476c-9621-2409ebdcbad9","content":"<p>A common feature of representative governments, malapportionment occurs when electoral districts are over- or underrepresented.</p>"},{"id":"051b5c47-e6c6-4bff-accc-922bf41e8fb0","content":"<p>Awarding more points per unit of land than points per resident, the formula for distributing Storting seats overrepresents less populated rural districts with large tracts of land.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["051b5c47-e6c6-4bff-accc-922bf41e8fb0"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. By noting that the formula for distributing Storting seats overrepresents less populated rural districts, the sentence effectively refutes a claim that malapportionment in the Storting favors small urban districts.</p><p>Choice A is incorrect because the sentence claims that malapportionment in the Storting favors small urban districts; it doesn&rsquo;t refute such a claim. Moreover, it misrepresents information in the notes. According to the notes, the formula for distributing seats overrepresents less populated, not more populated, districts. Choice B is incorrect. While the sentence appears to refute a claim that malapportionment in the Storting favors small urban districts, it misrepresents information in the notes. According to the notes, the formula for distributing seats overrepresents less populated, not more populated, districts. Choice C is incorrect. The sentence explains what malapportionment is but doesn&rsquo;t address malapportionment in the Storting specifically.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"07456405","external_id":"38a5c95b-f2c6-4f5c-95c4-9054cd57ded1","vaultid":null,"uId":"6d6d22d8-ebf9-440a-bad1-45cd3572d0d5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li><span> </span><span>Malapportionment is the over- or underrepresentation (relative to population size) of electoral districts in a governing body.</span></li>\n<li><span>It is a common feature of representative governments.</span></li>\n<li>There are 169 seats in Norway&rsquo;s supreme legislature (the Storting).</li>\n<li>Seats are distributed by a formula that awards 1 point per resident and 1.8 points per unit of land.</li>\n<li>Less populated rural districts with large tracts of land receive a disproportionate number of seats compared to smaller but more populated urban districts.</li>\n</ul>","stem":"<p>The student wants to refute a claim that malapportionment in the Storting favors small urban districts. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"5c33f4cf-fbdc-4b50-9298-45f8bc1986ae","content":"<p>Less populated rural districts are disproportionally underrepresented in the Storting, creating an unfair advantage for smaller but more populated urban districts.&nbsp;</p>"},{"id":"22a28d2a-6254-40e1-b824-d70e520801e5","content":"<p>It&rsquo;s untrue that malapportionment in the 169-seat Storting favors small urban districts; rather, the formula for distributing seats overrepresents more populated districts.</p>"},{"id":"37e84bce-22ab-476c-9621-2409ebdcbad9","content":"<p>A common feature of representative governments, malapportionment occurs when electoral districts are over- or underrepresented.</p>"},{"id":"051b5c47-e6c6-4bff-accc-922bf41e8fb0","content":"<p>Awarding more points per unit of land than points per resident, the formula for distributing Storting seats overrepresents less populated rural districts with large tracts of land.</p>"}],"keys":["051b5c47-e6c6-4bff-accc-922bf41e8fb0"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. By noting that the formula for distributing Storting seats overrepresents less populated rural districts, the sentence effectively refutes a claim that malapportionment in the Storting favors small urban districts.</p><p>Choice A is incorrect because the sentence claims that malapportionment in the Storting favors small urban districts; it doesn&rsquo;t refute such a claim. Moreover, it misrepresents information in the notes. According to the notes, the formula for distributing seats overrepresents less populated, not more populated, districts. Choice B is incorrect. While the sentence appears to refute a claim that malapportionment in the Storting favors small urban districts, it misrepresents information in the notes. According to the notes, the formula for distributing seats overrepresents less populated, not more populated, districts. Choice C is incorrect. The sentence explains what malapportionment is but doesn&rsquo;t address malapportionment in the Storting specifically.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669205,"updateDate":1743430669205}$SATQ$::jsonb, 1743430669205, 1743430669205),
    ($SATQ$0778b4ac$SATQ$, $SATQ$ff074c68-b388-4944-8a33-454dc0e67ca6$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Chromosomes are cellular structures that contain genes.</li>
<li>Genes carry critical instructions for determining an organism&rsquo;s physical traits.</li>
<li>Members of the same species typically have the same number of chromosomes.</li>
<li>The pineapple (<em>Ananas comosus</em>) and the melon (<em>Cucumis melo</em>) are species of fruits.</li>
<li>The pineapple has fifty chromosomes.</li>
<li>The melon has twenty-four chromosomes.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to specify how many chromosomes the pineapple has. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"93ae7786-77e3-4122-887a-dfbedee25265","content":"<p>The pineapple&rsquo;s chromosomes contain genes, which are critical to determining an organism&rsquo;s physical traits.</p>"},{"id":"b71b16b1-5afc-4fa4-a8ee-18bb5fc9dd57","content":"<p>The pineapple (<em>Ananas comosus</em>) has fifty chromosomes.</p>"},{"id":"b983d5f9-539e-495f-8ff5-5cdcec63dcd4","content":"<p>The pineapple (<em>Ananas comosus</em>) and the melon (<em>Cucumis melo</em>) both have chromosomes, but the pineapple has more than the melon does.&nbsp;&nbsp;</p>"},{"id":"7fe4a50e-db7c-4eb8-a894-7a6b67617910","content":"<p>The melon, a species of fruit, has twenty-four structures called chromosomes.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b71b16b1-5afc-4fa4-a8ee-18bb5fc9dd57"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence directly specifies how many chromosomes the pineapple has, as indicated in the notes: fifty.</p><p>Choice A is incorrect. While the sentence mentions the pineapple&rsquo;s chromosomes, it doesn&rsquo;t specify how many it has. Choice C is incorrect. The sentence indicates that the pineapple has more chromosomes than the melon; it doesn&rsquo;t specify the exact number of chromosomes the pineapple has. Choice D is incorrect. The sentence specifies how many chromosomes the melon has, not how many the pineapple has.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0778b4ac","external_id":"ff074c68-b388-4944-8a33-454dc0e67ca6","vaultid":null,"uId":"a1341f84-43b2-488a-9a69-f1852d162bad","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Chromosomes are cellular structures that contain genes.</li>\n<li>Genes carry critical instructions for determining an organism&rsquo;s physical traits.</li>\n<li>Members of the same species typically have the same number of chromosomes.</li>\n<li>The pineapple (<em>Ananas comosus</em>) and the melon (<em>Cucumis melo</em>) are species of fruits.</li>\n<li>The pineapple has fifty chromosomes.</li>\n<li>The melon has twenty-four chromosomes.</li>\n</ul>","stem":"<p>The student wants to specify how many chromosomes the pineapple has. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"93ae7786-77e3-4122-887a-dfbedee25265","content":"<p>The pineapple&rsquo;s chromosomes contain genes, which are critical to determining an organism&rsquo;s physical traits.</p>"},{"id":"b71b16b1-5afc-4fa4-a8ee-18bb5fc9dd57","content":"<p>The pineapple (<em>Ananas comosus</em>) has fifty chromosomes.</p>"},{"id":"b983d5f9-539e-495f-8ff5-5cdcec63dcd4","content":"<p>The pineapple (<em>Ananas comosus</em>) and the melon (<em>Cucumis melo</em>) both have chromosomes, but the pineapple has more than the melon does.&nbsp;&nbsp;</p>"},{"id":"7fe4a50e-db7c-4eb8-a894-7a6b67617910","content":"<p>The melon, a species of fruit, has twenty-four structures called chromosomes.</p>"}],"keys":["b71b16b1-5afc-4fa4-a8ee-18bb5fc9dd57"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence directly specifies how many chromosomes the pineapple has, as indicated in the notes: fifty.</p><p>Choice A is incorrect. While the sentence mentions the pineapple&rsquo;s chromosomes, it doesn&rsquo;t specify how many it has. Choice C is incorrect. The sentence indicates that the pineapple has more chromosomes than the melon; it doesn&rsquo;t specify the exact number of chromosomes the pineapple has. Choice D is incorrect. The sentence specifies how many chromosomes the melon has, not how many the pineapple has.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061193,"updateDate":1755117061193}$SATQ$::jsonb, 1755117061193, 1755117061193),
    ($SATQ$080a7b51$SATQ$, $SATQ$8115a153-89bc-4bb9-93c8-b68bd4d76f43$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Imagine a magazine that a reader has thrown away. This magazine is post-consumer waste, as it became waste after reaching the consumer. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the paper scraps left over from printing the magazine are pre-consumer waste, as they became waste before reaching the consumer.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"fd0d324b-ed6a-4bf9-b93f-77cb4a8c313d","content":"<p>By contrast,</p>"},{"id":"a11f4a13-5184-40d7-96f5-a29f908b3a25","content":"<p>For example,</p>"},{"id":"04d01f14-341b-46bc-a57f-20ebc6e4fa3b","content":"<p>As a result,</p>"},{"id":"9a4c534b-4c72-44e5-9d3a-30ce2c396cfa","content":"<p>Specifically,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["fd0d324b-ed6a-4bf9-b93f-77cb4a8c313d"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;By contrast&rdquo; logically signals that the information in this sentence&mdash;that paper scraps left over from printing a magazine are pre-consumer waste&mdash;contrasts with the previous information about magazines being post-consumer waste.</p><p>Choice B is incorrect because &ldquo;for example&rdquo; illogically signals that the information in this sentence exemplifies the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information. Choice C is incorrect because &ldquo;as a result&rdquo; illogically signals that the information in this sentence is a result or consequence of the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information. Choice D is incorrect because &ldquo;specifically&rdquo; illogically signals that the information in this sentence provides specific, precise details elaborating on the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"080a7b51","external_id":"8115a153-89bc-4bb9-93c8-b68bd4d76f43","vaultid":null,"uId":"37beddd1-2955-44ed-93c2-89bb10c53220","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Imagine a magazine that a reader has thrown away. This magazine is post-consumer waste, as it became waste after reaching the consumer. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the paper scraps left over from printing the magazine are pre-consumer waste, as they became waste before reaching the consumer.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"fd0d324b-ed6a-4bf9-b93f-77cb4a8c313d","content":"<p>By contrast,</p>"},{"id":"a11f4a13-5184-40d7-96f5-a29f908b3a25","content":"<p>For example,</p>"},{"id":"04d01f14-341b-46bc-a57f-20ebc6e4fa3b","content":"<p>As a result,</p>"},{"id":"9a4c534b-4c72-44e5-9d3a-30ce2c396cfa","content":"<p>Specifically,</p>"}],"keys":["fd0d324b-ed6a-4bf9-b93f-77cb4a8c313d"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;By contrast&rdquo; logically signals that the information in this sentence&mdash;that paper scraps left over from printing a magazine are pre-consumer waste&mdash;contrasts with the previous information about magazines being post-consumer waste.</p><p>Choice B is incorrect because &ldquo;for example&rdquo; illogically signals that the information in this sentence exemplifies the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information. Choice C is incorrect because &ldquo;as a result&rdquo; illogically signals that the information in this sentence is a result or consequence of the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information. Choice D is incorrect because &ldquo;specifically&rdquo; illogically signals that the information in this sentence provides specific, precise details elaborating on the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$0839a4b9$SATQ$, $SATQ$0bb1ffab-6a9a-4161-9e7c-65334c8df9ba$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The Coastal Futures Conservatory in Virginia is known for creating aural representations of ecological data. One such effort combines underwater audio recorded in seagrass beds with data that track rising carbon levels in the seagrass. As carbon levels increase, the audio is correspondingly distorted; <span aria-hidden="true">______</span><span class="sr-only">blank</span> listeners can &ldquo;hear&rdquo; the changes in the carbon levels.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"600c9ee9-04ea-4cfb-999b-26e6639360c4","content":"<p>furthermore,</p>"},{"id":"1817d896-56c9-4706-b920-42a27598755e","content":"<p>by comparison,</p>"},{"id":"a629c75c-b57d-4632-8e5c-448124d40835","content":"<p>for instance,</p>"},{"id":"01b0f23a-0a02-4c3e-a4ad-2a9fbca457de","content":"<p>thus,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["01b0f23a-0a02-4c3e-a4ad-2a9fbca457de"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Thus" logically signals that the information in this clause&mdash;that listeners can "hear" carbon levels increasing&mdash;is a result of the previous information about the audio distorting as carbon levels increase.</p><p>Choice A is incorrect because "furthermore" illogically signals that the information in this clause merely adds to the previous information about the audio distorting as carbon levels rise. Instead, the listeners&rsquo; ability to "hear" carbon levels increasing is a result of that distortion. Choice B is incorrect because "by comparison" illogically signals that the information in this clause is being compared to the information about the audio distorting as carbon levels rise. Instead, the listeners&rsquo; ability to "hear" carbon levels increasing is a result of that distortion. Choice C is incorrect because "for instance" illogically signals that the information in this clause is an example of how the audio distorts as carbon levels rise. Instead, the audio was distorted for the express purpose of representing ecological data; the listeners&rsquo; ability to "hear" carbon levels increasing is a direct, intended result of the distortion, not merely an example of it.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0839a4b9","external_id":"0bb1ffab-6a9a-4161-9e7c-65334c8df9ba","vaultid":null,"uId":"be9fb5c8-fd6b-41d2-af43-6dba6d817c89","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The Coastal Futures Conservatory in Virginia is known for creating aural representations of ecological data. One such effort combines underwater audio recorded in seagrass beds with data that track rising carbon levels in the seagrass. As carbon levels increase, the audio is correspondingly distorted; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> listeners can &ldquo;hear&rdquo; the changes in the carbon levels.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"600c9ee9-04ea-4cfb-999b-26e6639360c4","content":"<p>furthermore,</p>"},{"id":"1817d896-56c9-4706-b920-42a27598755e","content":"<p>by comparison,</p>"},{"id":"a629c75c-b57d-4632-8e5c-448124d40835","content":"<p>for instance,</p>"},{"id":"01b0f23a-0a02-4c3e-a4ad-2a9fbca457de","content":"<p>thus,</p>"}],"keys":["01b0f23a-0a02-4c3e-a4ad-2a9fbca457de"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Thus\" logically signals that the information in this clause&mdash;that listeners can \"hear\" carbon levels increasing&mdash;is a result of the previous information about the audio distorting as carbon levels increase.</p><p>Choice A is incorrect because \"furthermore\" illogically signals that the information in this clause merely adds to the previous information about the audio distorting as carbon levels rise. Instead, the listeners&rsquo; ability to \"hear\" carbon levels increasing is a result of that distortion. Choice B is incorrect because \"by comparison\" illogically signals that the information in this clause is being compared to the information about the audio distorting as carbon levels rise. Instead, the listeners&rsquo; ability to \"hear\" carbon levels increasing is a result of that distortion. Choice C is incorrect because \"for instance\" illogically signals that the information in this clause is an example of how the audio distorts as carbon levels rise. Instead, the audio was distorted for the express purpose of representing ecological data; the listeners&rsquo; ability to \"hear\" carbon levels increasing is a direct, intended result of the distortion, not merely an example of it.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$08be6347$SATQ$, $SATQ$ddfecfc5-e51c-4f19-b214-6395fa4bc1e7$SATQ$::uuid, $SATQ$ea15197c-2f2a-42a6-b59e-6980761f36bd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In his 1925 book <em>The Morphology of Landscape</em>,<em> </em>US geographer<em> </em>Carl Sauer challenged prevailing views about how natural landscapes influence human cultures. <span aria-hidden="true">______</span><span class="sr-only">blank</span> Sauer argued that instead of being shaped entirely by their natural surroundings, cultures play an active role in their own development by virtue of their interactions with the environment.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"757f161c-cc63-40fc-97a6-d9cf6860223c","content":"<p>Similarly,</p>"},{"id":"1d6f4fe5-0178-42e9-a2d0-d1fb47218295","content":"<p>Finally,</p>"},{"id":"abaf4f02-5e10-4ebf-a4d9-402aba089f24","content":"<p>Therefore,</p>"},{"id":"778d0767-41dc-45b7-8fa9-f8d731bbdb70","content":"<p>Specifically,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["778d0767-41dc-45b7-8fa9-f8d731bbdb70"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;Specifically&rdquo; logically signals that the information in this sentence about Sauer&rsquo;s argument&mdash;that, according to Sauer, cultures play a role in their own development, as opposed to being shaped solely by natural surroundings&mdash;provides specific, precise details elaborating on the more general information in the previous sentence about how Sauer challenged prevailing views about how natural landscapes influence human cultures. </p><p>Choice A is incorrect because &ldquo;similarly&rdquo; illogically signals that the information in this sentence about Sauer&rsquo;s argument is similar to, but separate from, the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information. Choice B is incorrect because &ldquo;finally&rdquo; illogically signals that the information in this sentence about Sauer&rsquo;s argument indicates a last step in a process or a concluding summary. Instead, it provides specific, precise details elaborating on the general information in the previous sentence. Choice C is incorrect because &ldquo;therefore&rdquo; illogically signals that the information in this sentence about Sauer&rsquo;s argument is a result of the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information. </p>$SATQ$, false, 0, $SATQ$OSP-228-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$a6e60f11-10c3-4745-94f4-f12b51c52c69$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"08be6347","external_id":"ddfecfc5-e51c-4f19-b214-6395fa4bc1e7","vaultid":"ea15197c-2f2a-42a6-b59e-6980761f36bd","uId":"70fcc9dd-ac3a-4d25-8207-6f2babaf77eb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In his 1925 book <em>The Morphology of Landscape</em>,<em> </em>US geographer<em> </em>Carl Sauer challenged prevailing views about how natural landscapes influence human cultures. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Sauer argued that instead of being shaped entirely by their natural surroundings, cultures play an active role in their own development by virtue of their interactions with the environment.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"757f161c-cc63-40fc-97a6-d9cf6860223c","content":"<p>Similarly,</p>"},{"id":"1d6f4fe5-0178-42e9-a2d0-d1fb47218295","content":"<p>Finally,</p>"},{"id":"abaf4f02-5e10-4ebf-a4d9-402aba089f24","content":"<p>Therefore,</p>"},{"id":"778d0767-41dc-45b7-8fa9-f8d731bbdb70","content":"<p>Specifically,</p>"}],"keys":["778d0767-41dc-45b7-8fa9-f8d731bbdb70"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;Specifically&rdquo; logically signals that the information in this sentence about Sauer&rsquo;s argument&mdash;that, according to Sauer, cultures play a role in their own development, as opposed to being shaped solely by natural surroundings&mdash;provides specific, precise details elaborating on the more general information in the previous sentence about how Sauer challenged prevailing views about how natural landscapes influence human cultures. </p><p>Choice A is incorrect because &ldquo;similarly&rdquo; illogically signals that the information in this sentence about Sauer&rsquo;s argument is similar to, but separate from, the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information. Choice B is incorrect because &ldquo;finally&rdquo; illogically signals that the information in this sentence about Sauer&rsquo;s argument indicates a last step in a process or a concluding summary. Instead, it provides specific, precise details elaborating on the general information in the previous sentence. Choice C is incorrect because &ldquo;therefore&rdquo; illogically signals that the information in this sentence about Sauer&rsquo;s argument is a result of the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information. </p>","parenttemplatename":"OSP-228-TRA","parenttemplateid":"","templateclusterid":"a6e60f11-10c3-4745-94f4-f12b51c52c69","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959332,"updateDate":1691007959332}$SATQ$::jsonb, 1691007959332, 1691007959332),
    ($SATQ$0acc26b2$SATQ$, $SATQ$55b902e4-fa91-44f6-8109-7dc4272cd236$SATQ$::uuid, $SATQ$a8a54983-d852-441f-bb9f-de6b701a4d97$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Astronomers estimate that the number of comets orbiting the Sun is in the billions.</li>
<li>81P/Wild is one of many comets whose orbit has changed over time.</li>
<li>81P/Wild&rsquo;s orbit once lay between the orbits of Uranus and Jupiter.</li>
<li>The comet&rsquo;s orbit is now positioned between the orbits of Jupiter and Mars.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to make and support a generalization about the orbits of comets. Which choice most effectively uses relevant information from the notes to accomplish these goals?&nbsp;</p>$SATQ$, $SATQ$[{"id":"ef0f2c93-cfae-4e09-8e43-338c74bec87d","content":"<p>Astronomers estimate that the number of comets orbiting the Sun is in the billions; the comets&rsquo; orbits may change over time.</p>"},{"id":"71ba1098-bd1e-4066-aee3-799841482d9b","content":"<p>Like Uranus, Jupiter, and Mars, billions of comets orbit the Sun.</p>"},{"id":"8656358a-2b9f-4aef-8b84-c6fa25100696","content":"<p>One example of a comet is 81P/Wild, whose orbit around the Sun once lay between Uranus&rsquo;s and Jupiter&rsquo;s orbits but is now positioned between those of Jupiter and Mars.</p>"},{"id":"35a1ffc7-f38e-4eea-9b33-60cc87f9534f","content":"<p>A comet&rsquo;s orbit around the Sun may change over time: the orbit of comet 81P/Wild once lay between the orbits of Uranus and Jupiter but is now positioned between those of Jupiter and Mars.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["35a1ffc7-f38e-4eea-9b33-60cc87f9534f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence makes a generalization&mdash;that a comet&rsquo;s orbit around the Sun may change over time&mdash;and supports the generalization with the example of the orbit of comet 81P/Wild, which once lay between the orbits of Uranus and Jupiter but is now positioned between the orbits of Jupiter and Mars. </p><p>Choice A is incorrect. The sentence emphasizes the number of comets orbiting the Sun and makes a generalization about their orbits, but it doesn&rsquo;t support the generalization with an example. Choice B is incorrect. The sentence makes a generalization about comets and compares them to the planets Uranus, Jupiter, and Mars; it doesn&rsquo;t make and support a generalization about comets&rsquo; orbits. Choice C is incorrect. While the sentence provides an example of a comet whose orbit has changed, it doesn&rsquo;t make a generalization about the orbits of comets. </p>$SATQ$, false, 0, $SATQ$OSP-765-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$4c586bda-5cee-4889-a050-f904eb0fb527$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0acc26b2","external_id":"55b902e4-fa91-44f6-8109-7dc4272cd236","vaultid":"a8a54983-d852-441f-bb9f-de6b701a4d97","uId":"82fd5c1d-343e-486a-9801-188e6be8b586","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Astronomers estimate that the number of comets orbiting the Sun is in the billions.</li>\n<li>81P/Wild is one of many comets whose orbit has changed over time.</li>\n<li>81P/Wild&rsquo;s orbit once lay between the orbits of Uranus and Jupiter.</li>\n<li>The comet&rsquo;s orbit is now positioned between the orbits of Jupiter and Mars.</li>\n</ul>","stem":"<p>The student wants to make and support a generalization about the orbits of comets. Which choice most effectively uses relevant information from the notes to accomplish these goals?&nbsp;</p>","answerOptions":[{"id":"ef0f2c93-cfae-4e09-8e43-338c74bec87d","content":"<p>Astronomers estimate that the number of comets orbiting the Sun is in the billions; the comets&rsquo; orbits may change over time.</p>"},{"id":"71ba1098-bd1e-4066-aee3-799841482d9b","content":"<p>Like Uranus, Jupiter, and Mars, billions of comets orbit the Sun.</p>"},{"id":"8656358a-2b9f-4aef-8b84-c6fa25100696","content":"<p>One example of a comet is 81P/Wild, whose orbit around the Sun once lay between Uranus&rsquo;s and Jupiter&rsquo;s orbits but is now positioned between those of Jupiter and Mars.</p>"},{"id":"35a1ffc7-f38e-4eea-9b33-60cc87f9534f","content":"<p>A comet&rsquo;s orbit around the Sun may change over time: the orbit of comet 81P/Wild once lay between the orbits of Uranus and Jupiter but is now positioned between those of Jupiter and Mars.</p>"}],"keys":["35a1ffc7-f38e-4eea-9b33-60cc87f9534f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence makes a generalization&mdash;that a comet&rsquo;s orbit around the Sun may change over time&mdash;and supports the generalization with the example of the orbit of comet 81P/Wild, which once lay between the orbits of Uranus and Jupiter but is now positioned between the orbits of Jupiter and Mars. </p><p>Choice A is incorrect. The sentence emphasizes the number of comets orbiting the Sun and makes a generalization about their orbits, but it doesn&rsquo;t support the generalization with an example. Choice B is incorrect. The sentence makes a generalization about comets and compares them to the planets Uranus, Jupiter, and Mars; it doesn&rsquo;t make and support a generalization about comets&rsquo; orbits. Choice C is incorrect. While the sentence provides an example of a comet whose orbit has changed, it doesn&rsquo;t make a generalization about the orbits of comets. </p>","parenttemplatename":"OSP-765-SYN","parenttemplateid":"","templateclusterid":"4c586bda-5cee-4889-a050-f904eb0fb527","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$0c0d50e1$SATQ$, $SATQ$2b9871d2-6c37-4b70-90c2-29d9b79984ab$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The Coastal Virginia Offshore Wind project is anticipated to generate 2.6 gigawatts of energy, enough to power almost one million homes. As its name indicates, the project&mdash;currently in development&mdash;consists of wind turbines located off the Virginia coast. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the project plan calls for 176 large turbines to be placed at a site 27 miles east of Virginia Beach.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"ff1bcab1-fb69-48af-bb49-40a1a99b6969","content":"<p>To be exact,</p>"},{"id":"b3e9f974-1241-442b-a749-264f39a6060d","content":"<p>In conclusion,</p>"},{"id":"c32c929a-f088-4cbd-a65b-5733159fc26e","content":"<p>As a result,</p>"},{"id":"4561a6aa-15fc-4ff3-b8e5-7a4801c04106","content":"<p>In contrast,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ff1bcab1-fb69-48af-bb49-40a1a99b6969"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "To be exact" logically signals that this sentence about the Coastal Virginia Offshore Wind project plan provides specific, precise details&mdash;number of turbines, location of site&mdash;elaborating on the more general information about the project in the previous sentence.</p><p>Choice B is incorrect because "in conclusion" illogically signals that the information in this sentence about the Coastal Virginia Offshore Wind project plan concludes or summarizes the discussion of the project in the previous sentences. Instead, the sentence provides specific, precise details elaborating on the previous information. Choice C is incorrect because "as a result" illogically signals that the information in this sentence about the Coastal Virginia Offshore Wind project plan is caused by, or occurs as a result of, the information about the project in the previous sentence. Instead, the sentence provides specific, precise details elaborating on the previous information. Choice D is incorrect because "in contrast" illogically signals that the information in this sentence about the Coastal Virginia Offshore Wind project plan contrasts with information about the project in the previous sentence. Instead, the sentence provides specific, precise details elaborating on the previous information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0c0d50e1","external_id":"2b9871d2-6c37-4b70-90c2-29d9b79984ab","vaultid":null,"uId":"4fd872d8-3f53-4888-a73f-4bd47cc28b16","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The Coastal Virginia Offshore Wind project is anticipated to generate 2.6 gigawatts of energy, enough to power almost one million homes. As its name indicates, the project&mdash;currently in development&mdash;consists of wind turbines located off the Virginia coast. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the project plan calls for 176 large turbines to be placed at a site 27 miles east of Virginia Beach.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"ff1bcab1-fb69-48af-bb49-40a1a99b6969","content":"<p>To be exact,</p>"},{"id":"b3e9f974-1241-442b-a749-264f39a6060d","content":"<p>In conclusion,</p>"},{"id":"c32c929a-f088-4cbd-a65b-5733159fc26e","content":"<p>As a result,</p>"},{"id":"4561a6aa-15fc-4ff3-b8e5-7a4801c04106","content":"<p>In contrast,</p>"}],"keys":["ff1bcab1-fb69-48af-bb49-40a1a99b6969"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"To be exact\" logically signals that this sentence about the Coastal Virginia Offshore Wind project plan provides specific, precise details&mdash;number of turbines, location of site&mdash;elaborating on the more general information about the project in the previous sentence.</p><p>Choice B is incorrect because \"in conclusion\" illogically signals that the information in this sentence about the Coastal Virginia Offshore Wind project plan concludes or summarizes the discussion of the project in the previous sentences. Instead, the sentence provides specific, precise details elaborating on the previous information. Choice C is incorrect because \"as a result\" illogically signals that the information in this sentence about the Coastal Virginia Offshore Wind project plan is caused by, or occurs as a result of, the information about the project in the previous sentence. Instead, the sentence provides specific, precise details elaborating on the previous information. Choice D is incorrect because \"in contrast\" illogically signals that the information in this sentence about the Coastal Virginia Offshore Wind project plan contrasts with information about the project in the previous sentence. Instead, the sentence provides specific, precise details elaborating on the previous information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669204,"updateDate":1743430669204}$SATQ$::jsonb, 1743430669204, 1743430669204),
    ($SATQ$0c13dea9$SATQ$, $SATQ$c8769440-175a-40e7-ba1d-ee7dc59b7872$SATQ$::uuid, $SATQ$6565efae-d7f8-47f7-83b7-cca1205e6c07$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The chemical trimethylamine N-oxide not only gives fish their fishy smell but also protects them from crushing hydrostatic pressure in deep waters. Trimethylamine N-oxide strengthens the bonds between water molecules in a fish&rsquo;s body. <span aria-hidden="true">______</span><span class="sr-only">blank</span> these water molecules maintain their linked structure at extreme depths, thus preventing pressure-related damage.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"6cdfa1d5-536e-464e-883c-dc18db1267cf","content":"<p>Nevertheless,</p>"},{"id":"f57d6508-feec-4a7e-86dc-51d9219ef263","content":"<p>As a result,</p>"},{"id":"41d12451-e16a-43fc-bb6d-3fe98ef7cb3e","content":"<p>However,</p>"},{"id":"65a2fd30-1ba7-45e0-ba24-dd2273a4f531","content":"<p>For instance,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["f57d6508-feec-4a7e-86dc-51d9219ef263"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;As a result&rdquo; indicates that water molecules maintaining their linked structure at high pressures is caused by the strengthening of these water molecules by trimethylamine N-oxide. So the transition &ldquo;as a result&rdquo; fits the context perfectly. </p><p>Choice A is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous one&mdash;rather, it&rsquo;s describing an effect of the phenomenon described in the previous sentence. Choice C is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous one; it actually expands on the previous sentence by describing an effect of the strengthened molecules. Choice D is incorrect. This choice uses an exemplification transition, which doesn&rsquo;t make sense here. The second sentence doesn&rsquo;t provide an example or instance of the idea in the previous sentence. Instead, it explores the effects of the previous idea in more depth. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-M009$SATQ$, $SATQ$$SATQ$, $SATQ$8f893139-79b7-4a75-8456-851298293492$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0c13dea9","external_id":"c8769440-175a-40e7-ba1d-ee7dc59b7872","vaultid":"6565efae-d7f8-47f7-83b7-cca1205e6c07","uId":"a425f474-f67d-4090-8d19-fb12da605994","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The chemical trimethylamine N-oxide not only gives fish their fishy smell but also protects them from crushing hydrostatic pressure in deep waters. Trimethylamine N-oxide strengthens the bonds between water molecules in a fish&rsquo;s body. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> these water molecules maintain their linked structure at extreme depths, thus preventing pressure-related damage.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"6cdfa1d5-536e-464e-883c-dc18db1267cf","content":"<p>Nevertheless,</p>"},{"id":"f57d6508-feec-4a7e-86dc-51d9219ef263","content":"<p>As a result,</p>"},{"id":"41d12451-e16a-43fc-bb6d-3fe98ef7cb3e","content":"<p>However,</p>"},{"id":"65a2fd30-1ba7-45e0-ba24-dd2273a4f531","content":"<p>For instance,</p>"}],"keys":["f57d6508-feec-4a7e-86dc-51d9219ef263"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;As a result&rdquo; indicates that water molecules maintaining their linked structure at high pressures is caused by the strengthening of these water molecules by trimethylamine N-oxide. So the transition &ldquo;as a result&rdquo; fits the context perfectly. </p><p>Choice A is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous one&mdash;rather, it&rsquo;s describing an effect of the phenomenon described in the previous sentence. Choice C is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous one; it actually expands on the previous sentence by describing an effect of the strengthened molecules. Choice D is incorrect. This choice uses an exemplification transition, which doesn&rsquo;t make sense here. The second sentence doesn&rsquo;t provide an example or instance of the idea in the previous sentence. Instead, it explores the effects of the previous idea in more depth. </p>","parenttemplatename":"OSP-KA-TRA-M009","parenttemplateid":"","templateclusterid":"8f893139-79b7-4a75-8456-851298293492","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959374,"updateDate":1691007959374}$SATQ$::jsonb, 1691007959374, 1691007959374),
    ($SATQ$0d088ae0$SATQ$, $SATQ$02f24d0d-074b-4881-9e60-75dd4957af39$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Observing that a fire in a closed container soon went out, leading eighteenth-century scientists did not conclude that fresh air (specifically, oxygen) is necessary for combustion; instead, many theorized that the container&rsquo;s air had become saturated with a substance called phlogiston. <span aria-hidden="true">______</span><span class="sr-only">blank</span> when Joseph Priestley first isolated oxygen gas in 1774, he termed it &ldquo;dephlogisticated air.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"4a477a67-2e57-4da8-941a-d34ddd23b0ae","content":"<p>In other words,</p>"},{"id":"e4b35d08-8b80-44e0-aae2-6ae80437bcfe","content":"<p>For this reason,</p>"},{"id":"3d41807a-be54-40ec-8f31-1ebbdad005e3","content":"<p>Alternatively,</p>"},{"id":"9e62ff6a-deaa-4927-89f9-27f6443016dc","content":"<p>Nevertheless,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e4b35d08-8b80-44e0-aae2-6ae80437bcfe"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "For this reason" logically signals that the reason Joseph Priestley termed oxygen "dephlogisticated air" was that he accepted the theory mentioned in the previous sentence&mdash;that the presence of phlogiston, rather than the absence of oxygen, causes fire in a closed container to go out.</p><p>Choice A is incorrect because "in other words" illogically signals that the information about Priestley terming oxygen "dephlogisticated air" is a restatement of the previous theory concerning phlogiston. Instead, Priestley chose the term as a result of this theory. Choice C is incorrect because "alternatively" illogically signals that Priestley termed oxygen "dephlogisticated air" as an alternative to the previous theory concerning phlogiston. Instead, Priestley chose the term as a result of this theory. Choice D is incorrect because "nevertheless" illogically signals that Priestley termed oxygen "dephlogisticated air" despite the previous theory concerning phlogiston. Instead, Priestley chose the term as a result of this theory.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0d088ae0","external_id":"02f24d0d-074b-4881-9e60-75dd4957af39","vaultid":null,"uId":"8643896d-3a76-471b-b6c5-00b982d4ae0a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Observing that a fire in a closed container soon went out, leading eighteenth-century scientists did not conclude that fresh air (specifically, oxygen) is necessary for combustion; instead, many theorized that the container&rsquo;s air had become saturated with a substance called phlogiston. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> when Joseph Priestley first isolated oxygen gas in 1774, he termed it &ldquo;dephlogisticated air.&rdquo;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"4a477a67-2e57-4da8-941a-d34ddd23b0ae","content":"<p>In other words,</p>"},{"id":"e4b35d08-8b80-44e0-aae2-6ae80437bcfe","content":"<p>For this reason,</p>"},{"id":"3d41807a-be54-40ec-8f31-1ebbdad005e3","content":"<p>Alternatively,</p>"},{"id":"9e62ff6a-deaa-4927-89f9-27f6443016dc","content":"<p>Nevertheless,</p>"}],"keys":["e4b35d08-8b80-44e0-aae2-6ae80437bcfe"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"For this reason\" logically signals that the reason Joseph Priestley termed oxygen \"dephlogisticated air\" was that he accepted the theory mentioned in the previous sentence&mdash;that the presence of phlogiston, rather than the absence of oxygen, causes fire in a closed container to go out.</p><p>Choice A is incorrect because \"in other words\" illogically signals that the information about Priestley terming oxygen \"dephlogisticated air\" is a restatement of the previous theory concerning phlogiston. Instead, Priestley chose the term as a result of this theory. Choice C is incorrect because \"alternatively\" illogically signals that Priestley termed oxygen \"dephlogisticated air\" as an alternative to the previous theory concerning phlogiston. Instead, Priestley chose the term as a result of this theory. Choice D is incorrect because \"nevertheless\" illogically signals that Priestley termed oxygen \"dephlogisticated air\" despite the previous theory concerning phlogiston. Instead, Priestley chose the term as a result of this theory.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$0d3ebdce$SATQ$, $SATQ$673e6351-f5cc-489a-9b61-548486364ffa$SATQ$::uuid, $SATQ$97da32e0-c2b0-4ab8-aced-884e8a169166$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Neuroscientist Karen Konkoly wanted to determine whether individuals can understand and respond to questions during REM sleep. She first taught volunteers eye movements they would use to respond to basic math problems while asleep (a single left-right eye movement indicated the number one). <span aria-hidden="true">______</span><span class="sr-only">blank</span> she attached electrodes to the volunteers&rsquo; faces to record their eye movements during sleep.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"29be820b-696c-493f-be80-3c349944bede","content":"<p>Specifically,</p>"},{"id":"372861ce-9b4f-4863-b754-8c70b33e6067","content":"<p>Next,</p>"},{"id":"56e90bd6-658b-4d3a-a441-7a5568aa1ce4","content":"<p>For instance,</p>"},{"id":"02e20c21-c232-4331-a079-138db77d107f","content":"<p>In sum,&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["372861ce-9b4f-4863-b754-8c70b33e6067"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;Next&rdquo; logically signals that the action described in this sentence&mdash;Konkoly recording participants&rsquo; eye movements&mdash;is the next step in Konkoly&rsquo;s experiment. </p><p>Choice A is incorrect because &ldquo;specifically&rdquo; illogically signals that this sentence specifies or elaborates on an aspect of the action described in the previous sentence. Instead, it describes the next step in Konkoly&rsquo;s experiment. Choice C is incorrect because &ldquo;for instance&rdquo; illogically signals that the action described in this sentence is an example of the action described in the previous sentence. Instead, it is the next step in Konkoly&rsquo;s experiment. Choice D is incorrect because &ldquo;in sum&rdquo; illogically signals that this sentence summarizes or concludes the action described in the previous sentence. Instead, it describes the next step in Konkoly&rsquo;s experiment. </p>$SATQ$, false, 0, $SATQ$OSP-218-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$9872eb65-2d07-46f0-9a8b-29c4c2b1fe10$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0d3ebdce","external_id":"673e6351-f5cc-489a-9b61-548486364ffa","vaultid":"97da32e0-c2b0-4ab8-aced-884e8a169166","uId":"34eb2e9f-9bc1-450a-838b-7df7def46799","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Neuroscientist Karen Konkoly wanted to determine whether individuals can understand and respond to questions during REM sleep. She first taught volunteers eye movements they would use to respond to basic math problems while asleep (a single left-right eye movement indicated the number one). <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> she attached electrodes to the volunteers&rsquo; faces to record their eye movements during sleep.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"29be820b-696c-493f-be80-3c349944bede","content":"<p>Specifically,</p>"},{"id":"372861ce-9b4f-4863-b754-8c70b33e6067","content":"<p>Next,</p>"},{"id":"56e90bd6-658b-4d3a-a441-7a5568aa1ce4","content":"<p>For instance,</p>"},{"id":"02e20c21-c232-4331-a079-138db77d107f","content":"<p>In sum,&nbsp;</p>"}],"keys":["372861ce-9b4f-4863-b754-8c70b33e6067"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;Next&rdquo; logically signals that the action described in this sentence&mdash;Konkoly recording participants&rsquo; eye movements&mdash;is the next step in Konkoly&rsquo;s experiment. </p><p>Choice A is incorrect because &ldquo;specifically&rdquo; illogically signals that this sentence specifies or elaborates on an aspect of the action described in the previous sentence. Instead, it describes the next step in Konkoly&rsquo;s experiment. Choice C is incorrect because &ldquo;for instance&rdquo; illogically signals that the action described in this sentence is an example of the action described in the previous sentence. Instead, it is the next step in Konkoly&rsquo;s experiment. Choice D is incorrect because &ldquo;in sum&rdquo; illogically signals that this sentence summarizes or concludes the action described in the previous sentence. Instead, it describes the next step in Konkoly&rsquo;s experiment. </p>","parenttemplatename":"OSP-218-TRA","parenttemplateid":"","templateclusterid":"9872eb65-2d07-46f0-9a8b-29c4c2b1fe10","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959327,"updateDate":1691007959327}$SATQ$::jsonb, 1691007959327, 1691007959327),
    ($SATQ$0ee64efc$SATQ$, $SATQ$ddfc47df-caff-477e-8e1f-b8f7acdcc509$SATQ$::uuid, $SATQ$e6c19ec1-04f9-474c-8679-ecd0b49a86ff$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In the 1850s, William Still was instrumental in helping nearly 1,000 people escape from slavery, earning him the moniker &ldquo;the Father of the Underground Railroad.&rdquo; <span aria-hidden="true">______</span><span class="sr-only">blank</span> despite the fame of his contributions during his lifetime, Still is discussed far less today than other prominent Black abolitionists from his era, such as Frederick Douglass and Harriet Tubman. &nbsp;&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"805b60d3-ece5-4cd4-9195-48d8dcf70f94","content":"<p>For example,</p>"},{"id":"a2d31ff5-fee2-4276-8988-a44a704235c8","content":"<p>However,</p>"},{"id":"e2139176-99ba-4ff5-96c5-be7b36c73ad6","content":"<p>Specifically,</p>"},{"id":"6b452c74-85a2-45be-b756-9d31ba07c3e5","content":"<p>Similarly,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a2d31ff5-fee2-4276-8988-a44a704235c8"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "However" is used to indicate a contrast between two ideas. The first sentence describes how Still used to be famous. This sentence describes how Still is not very famous today, so the transition "however" fits perfectly.</p><p>Choice A is incorrect. This choice uses a transition that introduces an example. But the second sentence doesn&rsquo;t provide a specific example of Still&rsquo;s famous contributions to the Underground Railroad. Instead, it changes the subject to how his fame has faded over time. Choice C is incorrect. This choice uses a transition that introduces an example or continuation of a previous idea. But the second sentence doesn&rsquo;t provide a specific example of Still&rsquo;s famous contributions to the Underground Railroad. Instead, it changes the subject to how his fame has faded over time. Choice D is incorrect. This choice uses a transition that indicates the agreement between two ideas. But this sentence shows a contrast with the first sentence&mdash;namely, that Still used to be very famous but now isn&rsquo;t very famous.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E008$SATQ$, $SATQ$$SATQ$, $SATQ$2ff097d1-f13d-47fc-81a0-4ef56501826e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0ee64efc","external_id":"ddfc47df-caff-477e-8e1f-b8f7acdcc509","vaultid":"e6c19ec1-04f9-474c-8679-ecd0b49a86ff","uId":"b5e3ec98-f3e6-474b-b597-516f44eaf893","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In the 1850s, William Still was instrumental in helping nearly 1,000 people escape from slavery, earning him the moniker &ldquo;the Father of the Underground Railroad.&rdquo; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> despite the fame of his contributions during his lifetime, Still is discussed far less today than other prominent Black abolitionists from his era, such as Frederick Douglass and Harriet Tubman. &nbsp;&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"805b60d3-ece5-4cd4-9195-48d8dcf70f94","content":"<p>For example,</p>"},{"id":"a2d31ff5-fee2-4276-8988-a44a704235c8","content":"<p>However,</p>"},{"id":"e2139176-99ba-4ff5-96c5-be7b36c73ad6","content":"<p>Specifically,</p>"},{"id":"6b452c74-85a2-45be-b756-9d31ba07c3e5","content":"<p>Similarly,</p>"}],"keys":["a2d31ff5-fee2-4276-8988-a44a704235c8"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"However\" is used to indicate a contrast between two ideas. The first sentence describes how Still used to be famous. This sentence describes how Still is not very famous today, so the transition \"however\" fits perfectly.</p><p>Choice A is incorrect. This choice uses a transition that introduces an example. But the second sentence doesn&rsquo;t provide a specific example of Still&rsquo;s famous contributions to the Underground Railroad. Instead, it changes the subject to how his fame has faded over time. Choice C is incorrect. This choice uses a transition that introduces an example or continuation of a previous idea. But the second sentence doesn&rsquo;t provide a specific example of Still&rsquo;s famous contributions to the Underground Railroad. Instead, it changes the subject to how his fame has faded over time. Choice D is incorrect. This choice uses a transition that indicates the agreement between two ideas. But this sentence shows a contrast with the first sentence&mdash;namely, that Still used to be very famous but now isn&rsquo;t very famous.</p>","parenttemplatename":"OSP-KA-TRA-E008","parenttemplateid":"","templateclusterid":"2ff097d1-f13d-47fc-81a0-4ef56501826e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$0f9ed134$SATQ$, $SATQ$f55fa46e-58cd-4be5-b3be-09243e83a490$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In 1974, Mexican chemist Mario Molina and US chemist <span data-ssml-sub-alias="F">F.</span> Sherwood Rowland discovered that chemicals called CFCs were harmful to the ozone layer. Their research was extremely influential in the fight against CFCs. <span aria-hidden="true">______</span><span class="sr-only">blank</span> it laid the foundation for a 1987 treaty that phased out the use of CFCs across the globe.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"4ce906b2-6513-4c53-b1c5-8e58e954299f","content":"<p>Regardless,</p>"},{"id":"b608d850-2190-445d-bec3-ff2a5ce1d522","content":"<p>Specifically,</p>"},{"id":"69b6845a-6821-481f-9230-d0b65f4dd71c","content":"<p>However,</p>"},{"id":"6d50a7cf-4473-4721-b3d6-701bef91e844","content":"<p>Earlier,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b608d850-2190-445d-bec3-ff2a5ce1d522"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "Specifically" logically signals that the information in this sentence&mdash;that Molina and Rowland&rsquo;s research laid the foundation for a later treaty&mdash;provides specific, precise details elaborating on the previous sentence&rsquo;s more general claim about the influence of the research.</p><p>Choice A is incorrect because "regardless" illogically signals that the information in this sentence is true despite the previous sentence&rsquo;s claim about the influence of Molina and Rowland&rsquo;s research. Instead, this information&mdash;that the research laid the foundation for a later treaty&mdash;provides specific details elaborating on the previous claim. Choice C is incorrect because "however" illogically signals that the information in this sentence contrasts with the previous sentence&rsquo;s claim about the influence of Molina and Rowland&rsquo;s research. Instead, this information&mdash;that the research laid the foundation for a later treaty&mdash;provides specific details elaborating on the previous claim. Choice D is incorrect because "earlier" illogically signals that the information in this sentence occurred at a time before Molina and Rowland&rsquo;s research influenced the fight against CFCs. Instead, this information&mdash;that the research laid the foundation for a later treaty&mdash;provides specific details elaborating on the previous claim about the research&rsquo;s influence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0f9ed134","external_id":"f55fa46e-58cd-4be5-b3be-09243e83a490","vaultid":null,"uId":"b36df0a9-7de7-4362-9ea8-75c293354afb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In 1974, Mexican chemist Mario Molina and US chemist <span data-ssml-sub-alias=\"F\">F.</span> Sherwood Rowland discovered that chemicals called CFCs were harmful to the ozone layer. Their research was extremely influential in the fight against CFCs. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> it laid the foundation for a 1987 treaty that phased out the use of CFCs across the globe.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"4ce906b2-6513-4c53-b1c5-8e58e954299f","content":"<p>Regardless,</p>"},{"id":"b608d850-2190-445d-bec3-ff2a5ce1d522","content":"<p>Specifically,</p>"},{"id":"69b6845a-6821-481f-9230-d0b65f4dd71c","content":"<p>However,</p>"},{"id":"6d50a7cf-4473-4721-b3d6-701bef91e844","content":"<p>Earlier,</p>"}],"keys":["b608d850-2190-445d-bec3-ff2a5ce1d522"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"Specifically\" logically signals that the information in this sentence&mdash;that Molina and Rowland&rsquo;s research laid the foundation for a later treaty&mdash;provides specific, precise details elaborating on the previous sentence&rsquo;s more general claim about the influence of the research.</p><p>Choice A is incorrect because \"regardless\" illogically signals that the information in this sentence is true despite the previous sentence&rsquo;s claim about the influence of Molina and Rowland&rsquo;s research. Instead, this information&mdash;that the research laid the foundation for a later treaty&mdash;provides specific details elaborating on the previous claim. Choice C is incorrect because \"however\" illogically signals that the information in this sentence contrasts with the previous sentence&rsquo;s claim about the influence of Molina and Rowland&rsquo;s research. Instead, this information&mdash;that the research laid the foundation for a later treaty&mdash;provides specific details elaborating on the previous claim. Choice D is incorrect because \"earlier\" illogically signals that the information in this sentence occurred at a time before Molina and Rowland&rsquo;s research influenced the fight against CFCs. Instead, this information&mdash;that the research laid the foundation for a later treaty&mdash;provides specific details elaborating on the previous claim about the research&rsquo;s influence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669215,"updateDate":1743430669215}$SATQ$::jsonb, 1743430669215, 1743430669215),
    ($SATQ$0fab0c90$SATQ$, $SATQ$d245bdf2-d209-40aa-a94a-fd9d8eac1fd6$SATQ$::uuid, $SATQ$bee4d55f-256e-4004-a547-6516049f6177$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The Gullah are a group of African Americans who have lived in parts of the southeastern United States since the 18th century.</li>
<li>Gullah culture is influenced by West African and Central African traditions.</li>
<li>Louise Miller Cohen is a Gullah historian, storyteller, and preservationist.</li>
<li>She founded the Gullah Museum of Hilton Head Island, South Carolina, in 2003.</li>
<li>Vermelle Rodrigues is a Gullah historian, artist, and preservationist.</li>
<li>She founded the Gullah Museum of Georgetown, South Carolina, in 2003.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the duration and purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"407e51f8-9343-4cf4-bdab-53c8154a98f5","content":"<p>At the Gullah Museums in Hilton Head Island and Georgetown, South Carolina, visitors can learn more about the Gullah people who have lived in the region for centuries.</p>"},{"id":"2e4c1232-9256-4dee-98d3-c9797079affb","content":"<p>Louise Miller Cohen and Vermelle Rodrigues have worked to preserve the culture of the Gullah people, who have lived in the United States since the 18th century.</p>"},{"id":"6e97d429-2a09-4d4d-8594-9dbeddf666b2","content":"<p>Since 2003, Louise Miller Cohen and Vermelle Rodrigues have worked to preserve Gullah culture through their museums.</p>"},{"id":"531b4a30-781a-41c8-8ae3-a5fc204030b5","content":"<p>Influenced by the traditions of West and Central Africa, Gullah culture developed in parts of the southeastern United States in the 18th century.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6e97d429-2a09-4d4d-8594-9dbeddf666b2"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes both the duration (the length of time) and the purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work by noting that the women have been working since 2003 to preserve Gullah culture.&nbsp;</p><p>Choice A is incorrect. While the sentence emphasizes what visitors to Cohen&rsquo;s and Rodrigues&rsquo;s museums can learn, it doesn&rsquo;t mention the duration or purpose of the women&rsquo;s work. Choice B is incorrect. While the sentence emphasizes the purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work, it doesn&rsquo;t mention the duration of that work (the length of time the women have been working to preserve Gullah culture).&nbsp;Choice D is incorrect. While the sentence emphasizes where and when Gullah culture developed, it doesn&rsquo;t mention the duration or purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work. </p>$SATQ$, false, 0, $SATQ$OSP-709-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$c86121d5-5b81-4ebc-9975-7c2683665879$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0fab0c90","external_id":"d245bdf2-d209-40aa-a94a-fd9d8eac1fd6","vaultid":"bee4d55f-256e-4004-a547-6516049f6177","uId":"780e53df-e0b6-4419-b5f1-9acc54b1709d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The Gullah are a group of African Americans who have lived in parts of the southeastern United States since the 18th century.</li>\n<li>Gullah culture is influenced by West African and Central African traditions.</li>\n<li>Louise Miller Cohen is a Gullah historian, storyteller, and preservationist.</li>\n<li>She founded the Gullah Museum of Hilton Head Island, South Carolina, in 2003.</li>\n<li>Vermelle Rodrigues is a Gullah historian, artist, and preservationist.</li>\n<li>She founded the Gullah Museum of Georgetown, South Carolina, in 2003.</li>\n</ul>","stem":"<p>The student wants to emphasize the duration and purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"407e51f8-9343-4cf4-bdab-53c8154a98f5","content":"<p>At the Gullah Museums in Hilton Head Island and Georgetown, South Carolina, visitors can learn more about the Gullah people who have lived in the region for centuries.</p>"},{"id":"2e4c1232-9256-4dee-98d3-c9797079affb","content":"<p>Louise Miller Cohen and Vermelle Rodrigues have worked to preserve the culture of the Gullah people, who have lived in the United States since the 18th century.</p>"},{"id":"6e97d429-2a09-4d4d-8594-9dbeddf666b2","content":"<p>Since 2003, Louise Miller Cohen and Vermelle Rodrigues have worked to preserve Gullah culture through their museums.</p>"},{"id":"531b4a30-781a-41c8-8ae3-a5fc204030b5","content":"<p>Influenced by the traditions of West and Central Africa, Gullah culture developed in parts of the southeastern United States in the 18th century.</p>"}],"keys":["6e97d429-2a09-4d4d-8594-9dbeddf666b2"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes both the duration (the length of time) and the purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work by noting that the women have been working since 2003 to preserve Gullah culture.&nbsp;</p><p>Choice A is incorrect. While the sentence emphasizes what visitors to Cohen&rsquo;s and Rodrigues&rsquo;s museums can learn, it doesn&rsquo;t mention the duration or purpose of the women&rsquo;s work. Choice B is incorrect. While the sentence emphasizes the purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work, it doesn&rsquo;t mention the duration of that work (the length of time the women have been working to preserve Gullah culture).&nbsp;Choice D is incorrect. While the sentence emphasizes where and when Gullah culture developed, it doesn&rsquo;t mention the duration or purpose of Cohen&rsquo;s and Rodrigues&rsquo;s work. </p>","parenttemplatename":"OSP-709-SYN","parenttemplateid":"","templateclusterid":"c86121d5-5b81-4ebc-9975-7c2683665879","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$0fd4df40$SATQ$, $SATQ$149f980e-e490-45de-816b-5d998b8dcad0$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The Alaska Native Language Archive (ANLA) is known for its impressive audio collection. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the ANLA has more than 5,000 audio recordings of Native Alaskan languages dating as far back as 1943.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"c01738ef-b17c-4ffb-9bca-f30a4b3a972d","content":"<p>In fact,</p>"},{"id":"1f081d74-6004-4bbf-b8cf-2f0c62c20b07","content":"<p>After,</p>"},{"id":"2addc819-e4bb-4270-b4cd-2aab8f99bb60","content":"<p>Regardless,&nbsp;</p>"},{"id":"b624d8d5-fbe6-4b39-a92e-2e88cf48290b","content":"<p>Instead,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["c01738ef-b17c-4ffb-9bca-f30a4b3a972d"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "In fact" logically signals that the information in this sentence about the large number of recordings in ANLA&rsquo;s collection emphasizes and supports the previous claim that ANLA is known for its impressive audio collection.</p><p>Choice B is incorrect because "after" illogically signals that the information in this sentence occurs later in a sequence of events than the previous claim about ANLA&rsquo;s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice C is incorrect because "regardless" illogically signals that the information in this sentence is true despite the previous claim about ANLA&rsquo;s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice D is incorrect because "instead" illogically signals that the information in this sentence presents an alternative to the previous claim about ANLA&rsquo;s impressive audio collection. Rather, the information about the large number of recordings emphasizes and supports that claim.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0fd4df40","external_id":"149f980e-e490-45de-816b-5d998b8dcad0","vaultid":null,"uId":"a90f6e18-3e31-44e9-be09-0d04a26128aa","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The Alaska Native Language Archive (ANLA) is known for its impressive audio collection. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the ANLA has more than 5,000 audio recordings of Native Alaskan languages dating as far back as 1943.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"c01738ef-b17c-4ffb-9bca-f30a4b3a972d","content":"<p>In fact,</p>"},{"id":"1f081d74-6004-4bbf-b8cf-2f0c62c20b07","content":"<p>After,</p>"},{"id":"2addc819-e4bb-4270-b4cd-2aab8f99bb60","content":"<p>Regardless,&nbsp;</p>"},{"id":"b624d8d5-fbe6-4b39-a92e-2e88cf48290b","content":"<p>Instead,</p>"}],"keys":["c01738ef-b17c-4ffb-9bca-f30a4b3a972d"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"In fact\" logically signals that the information in this sentence about the large number of recordings in ANLA&rsquo;s collection emphasizes and supports the previous claim that ANLA is known for its impressive audio collection.</p><p>Choice B is incorrect because \"after\" illogically signals that the information in this sentence occurs later in a sequence of events than the previous claim about ANLA&rsquo;s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice C is incorrect because \"regardless\" illogically signals that the information in this sentence is true despite the previous claim about ANLA&rsquo;s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice D is incorrect because \"instead\" illogically signals that the information in this sentence presents an alternative to the previous claim about ANLA&rsquo;s impressive audio collection. Rather, the information about the large number of recordings emphasizes and supports that claim.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669203,"updateDate":1743430669203}$SATQ$::jsonb, 1743430669203, 1743430669203),
    ($SATQ$10cd0327$SATQ$, $SATQ$dc77d8af-b008-45d8-9aca-c7b953781539$SATQ$::uuid, $SATQ$0f0b692a-528d-4eb7-aa58-b0874ddc2680$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>A thermal inversion is a phenomenon where a layer of atmosphere is warmer than the layer beneath it.</li>
<li>In 2022, a team of researchers studied the presence of thermal inversions in twenty-five gas giants.</li>
<li>Gas giants are planets largely composed of helium and hydrogen.</li>
<li>The team found that gas giants featuring a thermal inversion were also likely to contain heat-absorbing metals.</li>
<li>One explanation for this relationship is that these metals may reside in a planet&rsquo;s upper atmosphere, where their absorbed heat causes an increase in temperature.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to present the study&rsquo;s findings to an audience already familiar with thermal inversions. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"58211a21-49cd-4904-a5b3-8e82756b18b3","content":"<p>Heat-absorbing metals may reside in a planet&rsquo;s upper atmosphere.</p>"},{"id":"cf38ce86-fb30-46c2-9149-c3173e083fb3","content":"<p>The team studied thermal inversions in twenty-five gas giants, which are largely composed of helium and hydrogen.</p>"},{"id":"5abc407c-281c-419b-be9f-ed65de5827f9","content":"<p>Researchers found that gas giants featuring a thermal inversion were likely to contain heat-absorbing metals, which may reside in the planets&rsquo; upper atmospheres.</p>"},{"id":"01b7526b-9860-4890-939b-9577f7a1e5da","content":"<p>Gas giants were likely to contain heat-absorbing metals when they featured a layer of atmosphere warmer than the layer beneath it, researchers found; this phenomenon is known as a thermal inversion.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["5abc407c-281c-419b-be9f-ed65de5827f9"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. It describes the study&rsquo;s findings in a way that assumes the audience is already familiar with thermal inversions. </p><p>Choice A is incorrect. This choice doesn&rsquo;t fully describe the findings of the study, because it doesn&rsquo;t include anything about thermal inversions. Choice B is incorrect. This choice doesn&rsquo;t describe the study&rsquo;s findings. Choice D is incorrect. This choice isn&rsquo;t suited for an audience already familiar with thermal inversion. A familiar audience wouldn&rsquo;t need to have the term defined. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-H004$SATQ$, $SATQ$$SATQ$, $SATQ$e3acd36e-2ad2-436c-8bee-b6128b88cbc9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"10cd0327","external_id":"dc77d8af-b008-45d8-9aca-c7b953781539","vaultid":"0f0b692a-528d-4eb7-aa58-b0874ddc2680","uId":"7ad40094-846d-407c-9677-8a1b08bd0a91","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>A thermal inversion is a phenomenon where a layer of atmosphere is warmer than the layer beneath it.</li>\n<li>In 2022, a team of researchers studied the presence of thermal inversions in twenty-five gas giants.</li>\n<li>Gas giants are planets largely composed of helium and hydrogen.</li>\n<li>The team found that gas giants featuring a thermal inversion were also likely to contain heat-absorbing metals.</li>\n<li>One explanation for this relationship is that these metals may reside in a planet&rsquo;s upper atmosphere, where their absorbed heat causes an increase in temperature.</li>\n</ul>","stem":"<p>The student wants to present the study&rsquo;s findings to an audience already familiar with thermal inversions. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"58211a21-49cd-4904-a5b3-8e82756b18b3","content":"<p>Heat-absorbing metals may reside in a planet&rsquo;s upper atmosphere.</p>"},{"id":"cf38ce86-fb30-46c2-9149-c3173e083fb3","content":"<p>The team studied thermal inversions in twenty-five gas giants, which are largely composed of helium and hydrogen.</p>"},{"id":"5abc407c-281c-419b-be9f-ed65de5827f9","content":"<p>Researchers found that gas giants featuring a thermal inversion were likely to contain heat-absorbing metals, which may reside in the planets&rsquo; upper atmospheres.</p>"},{"id":"01b7526b-9860-4890-939b-9577f7a1e5da","content":"<p>Gas giants were likely to contain heat-absorbing metals when they featured a layer of atmosphere warmer than the layer beneath it, researchers found; this phenomenon is known as a thermal inversion.</p>"}],"keys":["5abc407c-281c-419b-be9f-ed65de5827f9"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. It describes the study&rsquo;s findings in a way that assumes the audience is already familiar with thermal inversions. </p><p>Choice A is incorrect. This choice doesn&rsquo;t fully describe the findings of the study, because it doesn&rsquo;t include anything about thermal inversions. Choice B is incorrect. This choice doesn&rsquo;t describe the study&rsquo;s findings. Choice D is incorrect. This choice isn&rsquo;t suited for an audience already familiar with thermal inversion. A familiar audience wouldn&rsquo;t need to have the term defined. </p>","parenttemplatename":"OSP-KA-SYN-H004","parenttemplateid":"","templateclusterid":"e3acd36e-2ad2-436c-8bee-b6128b88cbc9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$113f16da$SATQ$, $SATQ$037f245a-6646-44a6-8158-7ee6c14c8f36$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Some animals have evolved to physically resemble another animal, plant, or object.</li>
<li>This is known as mimicry.</li>
<li>Crab spiders mimic the appearance of flowers.</li>
<li>This helps crab spiders ambush their prey.</li>
<li>Katydids mimic the appearance of leaves.</li>
<li>This helps katydids hide from their predators.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a difference in how katydids and crab spiders use mimicry. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"dfd86679-45fa-4d1a-a7f8-63c100a84eb1","content":"<p>Katydids mimic the appearance of flowers, and crab spiders mimic that of leaves.&nbsp;</p>"},{"id":"e4b9e1b4-c727-4a0e-89bd-3e9efce7f197","content":"<p>Katydids and crab spiders are two examples of animals that use mimicry.</p>"},{"id":"2e5b3c02-95ac-4b0d-8085-42b5aa9a35d8","content":"<p>Unlike crab spiders, which use mimicry to ambush prey, katydids use mimicry to hide from predators.</p>"},{"id":"56c003b8-ace9-40fc-a113-86fe364d6aff","content":"<p>Animals that use mimicry have evolved to resemble another animal, plant, or object.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["2e5b3c02-95ac-4b0d-8085-42b5aa9a35d8"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence uses "unlike" to emphasize a difference in how katydids and crab spiders use mimicry, noting that crab spiders use mimicry to ambush prey while katydids use it to hide from predators.</p><p>Choice A is incorrect. While the sentence does contrast katydids and crab spiders, it misrepresents the information in the notes. Katydids mimic the appearance of leaves (not flowers), whereas crab spiders mimic the appearance of flowers (not leaves). Choice B is incorrect. While the sentence indicates that katydids and crab spiders use mimicry, it doesn&rsquo;t emphasize a difference in how they use it. Choice D is incorrect. The sentence describes what mimicry is; it doesn&rsquo;t emphasize a difference in how katydids and crab spiders specifically use mimicry.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"113f16da","external_id":"037f245a-6646-44a6-8158-7ee6c14c8f36","vaultid":null,"uId":"4dd74ffd-49d1-439c-bb42-382a286a14a7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Some animals have evolved to physically resemble another animal, plant, or object.</li>\n<li>This is known as mimicry.</li>\n<li>Crab spiders mimic the appearance of flowers.</li>\n<li>This helps crab spiders ambush their prey.</li>\n<li>Katydids mimic the appearance of leaves.</li>\n<li>This helps katydids hide from their predators.</li>\n</ul>","stem":"<p>The student wants to emphasize a difference in how katydids and crab spiders use mimicry. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"dfd86679-45fa-4d1a-a7f8-63c100a84eb1","content":"<p>Katydids mimic the appearance of flowers, and crab spiders mimic that of leaves.&nbsp;</p>"},{"id":"e4b9e1b4-c727-4a0e-89bd-3e9efce7f197","content":"<p>Katydids and crab spiders are two examples of animals that use mimicry.</p>"},{"id":"2e5b3c02-95ac-4b0d-8085-42b5aa9a35d8","content":"<p>Unlike crab spiders, which use mimicry to ambush prey, katydids use mimicry to hide from predators.</p>"},{"id":"56c003b8-ace9-40fc-a113-86fe364d6aff","content":"<p>Animals that use mimicry have evolved to resemble another animal, plant, or object.</p>"}],"keys":["2e5b3c02-95ac-4b0d-8085-42b5aa9a35d8"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence uses \"unlike\" to emphasize a difference in how katydids and crab spiders use mimicry, noting that crab spiders use mimicry to ambush prey while katydids use it to hide from predators.</p><p>Choice A is incorrect. While the sentence does contrast katydids and crab spiders, it misrepresents the information in the notes. Katydids mimic the appearance of leaves (not flowers), whereas crab spiders mimic the appearance of flowers (not leaves). Choice B is incorrect. While the sentence indicates that katydids and crab spiders use mimicry, it doesn&rsquo;t emphasize a difference in how they use it. Choice D is incorrect. The sentence describes what mimicry is; it doesn&rsquo;t emphasize a difference in how katydids and crab spiders specifically use mimicry.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$114bbce6$SATQ$, $SATQ$6368be96-9720-4d31-8ba0-50e38b991f78$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Earthquakes start at a point called a &ldquo;focus&rdquo; and spread out from there as seismic waves.</li>
<li>The two types of seismic waves that travel beneath Earth&rsquo;s surface are primary waves (P waves) and secondary waves (S waves).</li>
<li>P waves travel more quickly beneath Earth&rsquo;s surface than do S waves.</li>
<li>P waves compress and expand the ground, causing it to move backward and forward.</li>
<li>S waves cause the ground to move from side to side.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a similarity between P waves and S waves. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"cce57f64-6321-43c9-872c-4f8ecea4c5d1","content":"<p>P waves and S waves both travel beneath Earth&rsquo;s surface, causing the ground to move.</p>"},{"id":"5c536e78-1bdd-4197-82ac-d9b1548942eb","content":"<p>P waves travel away from an earthquake&rsquo;s starting point at a higher rate of speed than do S waves.</p>"},{"id":"c960c01f-c4c6-47de-81d3-b7851b75f6fd","content":"<p>Spreading out from the focus of an earthquake, P waves move the ground backward and forward.</p>"},{"id":"5db04080-f20a-4a99-a09d-03ad288493af","content":"<p>Although P waves and S waves start at the same point, they behave very differently.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["cce57f64-6321-43c9-872c-4f8ecea4c5d1"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence emphasizes a similarity between P waves and S waves, noting that they both travel beneath Earth&rsquo;s surface, thereby causing the ground to move.</p><p>Choice B is incorrect. The sentence emphasizes a difference between P waves and S waves, noting that P waves travel faster than S waves; it doesn&rsquo;t emphasize a similarity between the two types of waves. Choice C is incorrect. The sentence emphasizes how P waves move; it doesn&rsquo;t emphasize a similarity between P waves and S waves. Choice D is incorrect. While the sentence acknowledges that P waves and S waves start at the same point, it doesn&rsquo;t emphasize a similarity; instead, the sentence emphasizes a difference between the two types of waves, noting that they behave very differently.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"114bbce6","external_id":"6368be96-9720-4d31-8ba0-50e38b991f78","vaultid":null,"uId":"cc96a7b4-1c60-4a16-9bb1-90210cb498ec","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Earthquakes start at a point called a &ldquo;focus&rdquo; and spread out from there as seismic waves.</li>\n<li>The two types of seismic waves that travel beneath Earth&rsquo;s surface are primary waves (P waves) and secondary waves (S waves).</li>\n<li>P waves travel more quickly beneath Earth&rsquo;s surface than do S waves.</li>\n<li>P waves compress and expand the ground, causing it to move backward and forward.</li>\n<li>S waves cause the ground to move from side to side.</li>\n</ul>","stem":"<p>The student wants to emphasize a similarity between P waves and S waves. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"cce57f64-6321-43c9-872c-4f8ecea4c5d1","content":"<p>P waves and S waves both travel beneath Earth&rsquo;s surface, causing the ground to move.</p>"},{"id":"5c536e78-1bdd-4197-82ac-d9b1548942eb","content":"<p>P waves travel away from an earthquake&rsquo;s starting point at a higher rate of speed than do S waves.</p>"},{"id":"c960c01f-c4c6-47de-81d3-b7851b75f6fd","content":"<p>Spreading out from the focus of an earthquake, P waves move the ground backward and forward.</p>"},{"id":"5db04080-f20a-4a99-a09d-03ad288493af","content":"<p>Although P waves and S waves start at the same point, they behave very differently.</p>"}],"keys":["cce57f64-6321-43c9-872c-4f8ecea4c5d1"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence emphasizes a similarity between P waves and S waves, noting that they both travel beneath Earth&rsquo;s surface, thereby causing the ground to move.</p><p>Choice B is incorrect. The sentence emphasizes a difference between P waves and S waves, noting that P waves travel faster than S waves; it doesn&rsquo;t emphasize a similarity between the two types of waves. Choice C is incorrect. The sentence emphasizes how P waves move; it doesn&rsquo;t emphasize a similarity between P waves and S waves. Choice D is incorrect. While the sentence acknowledges that P waves and S waves start at the same point, it doesn&rsquo;t emphasize a similarity; instead, the sentence emphasizes a difference between the two types of waves, noting that they behave very differently.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$11df9b99$SATQ$, $SATQ$b65ede14-ac4e-4dd8-8b53-58d5ed2a89e7$SATQ$::uuid, $SATQ$adc58c37-44b9-41b7-a8bf-e4174bae91cf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Because an achiral molecule is symmetrical, flipping it yields a structurally identical molecule. A flipped chiral molecule, <span aria-hidden="true">______</span><span class="sr-only">blank</span> can be compared to a glove that has been turned inside out: it produces a structurally inverted molecule rather than an identical one.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"de1124a4-6e46-4b23-86ff-7b9eecfc5d0e","content":"<p>in other words,</p>"},{"id":"92f4d411-1589-4891-8169-9055a079f159","content":"<p>by contrast,</p>"},{"id":"a7a90906-6f9f-4cbd-9dcb-ccdba235d0ee","content":"<p>for example,</p>"},{"id":"2266cbc3-617e-4efb-9ad2-23d0303db9c1","content":"<p>similarly,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["92f4d411-1589-4891-8169-9055a079f159"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This sentence compares a chiral molecule to an achiral one. It discusses how when a chiral molecule is flipped, it results in something very different than when an achiral molecule is flipped. So the transition "by contrast" fits the context perfectly.</p><p>Choice A is incorrect. This choice uses a transition that indicates a restatement of the same idea in different words. But this sentence doesn&rsquo;t restate the same idea as the previous sentence. Instead, it makes a new point about a different type of molecule (chiral instead of achiral). Choice C is incorrect. This choice uses a transition that introduces an example, which doesn&rsquo;t make sense here. The second sentence isn&rsquo;t an example of the first sentence&rsquo;s claim about achiral molecules: it actually introduces an entirely different idea that focuses on chiral molecules. Choice D is incorrect. This choice uses a transition that indicates the addition of an agreeing idea. But this sentence shows a contrast with the first sentence&mdash;namely, that a chiral molecule acts very differently from an achiral molecule when flipped.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-M008$SATQ$, $SATQ$$SATQ$, $SATQ$72da21a7-9fbb-499a-9241-25a57a2eefcc$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"11df9b99","external_id":"b65ede14-ac4e-4dd8-8b53-58d5ed2a89e7","vaultid":"adc58c37-44b9-41b7-a8bf-e4174bae91cf","uId":"2933eea3-28a0-4d83-9c0d-8dca66737aeb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Because an achiral molecule is symmetrical, flipping it yields a structurally identical molecule. A flipped chiral molecule, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> can be compared to a glove that has been turned inside out: it produces a structurally inverted molecule rather than an identical one.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"de1124a4-6e46-4b23-86ff-7b9eecfc5d0e","content":"<p>in other words,</p>"},{"id":"92f4d411-1589-4891-8169-9055a079f159","content":"<p>by contrast,</p>"},{"id":"a7a90906-6f9f-4cbd-9dcb-ccdba235d0ee","content":"<p>for example,</p>"},{"id":"2266cbc3-617e-4efb-9ad2-23d0303db9c1","content":"<p>similarly,</p>"}],"keys":["92f4d411-1589-4891-8169-9055a079f159"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This sentence compares a chiral molecule to an achiral one. It discusses how when a chiral molecule is flipped, it results in something very different than when an achiral molecule is flipped. So the transition \"by contrast\" fits the context perfectly.</p><p>Choice A is incorrect. This choice uses a transition that indicates a restatement of the same idea in different words. But this sentence doesn&rsquo;t restate the same idea as the previous sentence. Instead, it makes a new point about a different type of molecule (chiral instead of achiral). Choice C is incorrect. This choice uses a transition that introduces an example, which doesn&rsquo;t make sense here. The second sentence isn&rsquo;t an example of the first sentence&rsquo;s claim about achiral molecules: it actually introduces an entirely different idea that focuses on chiral molecules. Choice D is incorrect. This choice uses a transition that indicates the addition of an agreeing idea. But this sentence shows a contrast with the first sentence&mdash;namely, that a chiral molecule acts very differently from an achiral molecule when flipped.</p>","parenttemplatename":"OSP-KA-TRA-M008","parenttemplateid":"","templateclusterid":"72da21a7-9fbb-499a-9241-25a57a2eefcc","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959374,"updateDate":1691007959374}$SATQ$::jsonb, 1691007959374, 1691007959374),
    ($SATQ$129089b5$SATQ$, $SATQ$eb908c22-f0e5-4e8e-a74a-9e02f9aaf2e1$SATQ$::uuid, $SATQ$f033d3b9-4eec-41b6-a84c-f6e3a0300471$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In 1933, the Twentieth Amendment to the US Constitution was ratified. The amendment mandates that presidential inaugurations be held on January 20, approximately ten weeks after the November election. <span aria-hidden="true">______</span><span class="sr-only">blank</span> this amendment requires newly elected US senators and representatives to be sworn into their respective offices on January 3.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"5ec3dfc0-ea3b-481a-9dad-37422d9825c9","content":"<p>Instead,</p>"},{"id":"68d184aa-26cc-4748-9509-ee64dd69f83e","content":"<p>For instance,</p>"},{"id":"5950e511-8571-4a6f-b5b7-bf90c8183935","content":"<p>Specifically,</p>"},{"id":"36ca7b9f-c1db-4335-aeae-f779138756a3","content":"<p>In addition,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["36ca7b9f-c1db-4335-aeae-f779138756a3"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;In addition&rdquo; logically signals that the information in this sentence&mdash;that the Twentieth Amendment requires newly elected US senators and representatives to be sworn in on January 3&mdash;is separate from and additional to the amendment&rsquo;s mandate concerning presidential inaugurations. </p><p>Choice A is incorrect because &ldquo;instead&rdquo; illogically signals that the information in the sentence presents an alternative to or substitute for the Twentieth Amendment&rsquo;s mandate concerning presidential inaugurations. Rather, the sentence presents a separate requirement in addition to that one. Choice B is incorrect because &ldquo;for instance&rdquo; illogically signals that the information in the sentence exemplifies the Twentieth Amendment&rsquo;s mandate concerning presidential inaugurations. Instead, the sentence presents a separate requirement in addition to that one. Choice C is incorrect because &ldquo;specifically&rdquo; illogically signals that the sentence provides specific, precise details elaborating on the Twentieth Amendment&rsquo;s mandate concerning presidential inaugurations. Instead, the sentence presents a separate requirement in addition to that one. </p>$SATQ$, false, 0, $SATQ$OSP-227-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$f1928790-de07-4915-82a2-8298c8f99960$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"129089b5","external_id":"eb908c22-f0e5-4e8e-a74a-9e02f9aaf2e1","vaultid":"f033d3b9-4eec-41b6-a84c-f6e3a0300471","uId":"552e11ed-c828-4349-99d9-89642609aa4d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In 1933, the Twentieth Amendment to the US Constitution was ratified. The amendment mandates that presidential inaugurations be held on January 20, approximately ten weeks after the November election. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> this amendment requires newly elected US senators and representatives to be sworn into their respective offices on January 3.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"5ec3dfc0-ea3b-481a-9dad-37422d9825c9","content":"<p>Instead,</p>"},{"id":"68d184aa-26cc-4748-9509-ee64dd69f83e","content":"<p>For instance,</p>"},{"id":"5950e511-8571-4a6f-b5b7-bf90c8183935","content":"<p>Specifically,</p>"},{"id":"36ca7b9f-c1db-4335-aeae-f779138756a3","content":"<p>In addition,</p>"}],"keys":["36ca7b9f-c1db-4335-aeae-f779138756a3"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;In addition&rdquo; logically signals that the information in this sentence&mdash;that the Twentieth Amendment requires newly elected US senators and representatives to be sworn in on January 3&mdash;is separate from and additional to the amendment&rsquo;s mandate concerning presidential inaugurations. </p><p>Choice A is incorrect because &ldquo;instead&rdquo; illogically signals that the information in the sentence presents an alternative to or substitute for the Twentieth Amendment&rsquo;s mandate concerning presidential inaugurations. Rather, the sentence presents a separate requirement in addition to that one. Choice B is incorrect because &ldquo;for instance&rdquo; illogically signals that the information in the sentence exemplifies the Twentieth Amendment&rsquo;s mandate concerning presidential inaugurations. Instead, the sentence presents a separate requirement in addition to that one. Choice C is incorrect because &ldquo;specifically&rdquo; illogically signals that the sentence provides specific, precise details elaborating on the Twentieth Amendment&rsquo;s mandate concerning presidential inaugurations. Instead, the sentence presents a separate requirement in addition to that one. </p>","parenttemplatename":"OSP-227-TRA","parenttemplateid":"","templateclusterid":"f1928790-de07-4915-82a2-8298c8f99960","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959332,"updateDate":1691007959332}$SATQ$::jsonb, 1691007959332, 1691007959332),
    ($SATQ$13f36b03$SATQ$, $SATQ$d97a955a-4eec-46ae-8d6f-3b584b6056d1$SATQ$::uuid, $SATQ$6b6128a8-a3aa-49d7-95af-e2b3c3ecf68f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Jon Ching is a Los Angeles-based painter.</li>
<li>He uses the term &ldquo;flauna&rdquo; to describe the plant-animal hybrids that he depicts in his surreal paintings.</li>
<li>&ldquo;Flauna&rdquo; is a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna.&rdquo;</li>
<li>His painting <em>Nectar </em>depicts a parrot with leaves for feathers.</li>
<li>His painting <em>Primaveral </em>depicts a snow leopard whose fur sprouts flowers.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to provide an explanation and example of &ldquo;flauna.&rdquo; Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"602bb841-876b-405a-8b4c-f7be25dee8ad","content":"<p>The term &ldquo;flauna,&rdquo; used by Los Angeles-based painter Jon Ching, is a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna.&rdquo;</p>"},{"id":"660bba88-af44-433c-85a4-b17b19516b8a","content":"<p>Jon Ching uses the term &ldquo;flauna,&rdquo; a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna,&rdquo; to describe the subjects of his surreal paintings: plant-animal hybrids such as a parrot with leaves for feathers.</p>"},{"id":"1d2bb99e-859d-4a55-b916-661904c5469b","content":"<p>Jon Ching, who created <em>Nectar</em>, refers to the subjects of his paintings as &ldquo;flauna.&rdquo;</p>"},{"id":"c48f409d-ba9d-43cc-9833-6ce2ff362008","content":"<p>The subjects of <em>Nectar </em>and <em>Primaveral </em>are types of &ldquo;flauna,&rdquo; a term that the paintings&rsquo; creator, Jon Ching, uses when describing his surreal artworks.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["660bba88-af44-433c-85a4-b17b19516b8a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it provides both an explanation and an example of &ldquo;flauna.&rdquo; The sentence explains that flauna, a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna,&rdquo; is a term used by Jon Ching to describe the plant-animal hybrids in his paintings. The sentence also mentions an example of Ching&rsquo;s flauna: a parrot with leaves for feathers.&nbsp;</p><p>Choice A is incorrect. While the sentence partially explains what &ldquo;flauna&rdquo; is, it doesn&rsquo;t provide a full explanation or specific example of Ching&rsquo;s flauna. Choice C is incorrect. While the sentence partially explains what &ldquo;flauna&rdquo; is and includes a title of a Ching painting, it doesn&rsquo;t provide a full explanation or specific example of Ching&rsquo;s flauna. Choice D is incorrect. While the sentence partially explains what &ldquo;flauna&rdquo; is and includes the titles of two Ching paintings, it doesn&rsquo;t provide a full explanation of Ching&rsquo;s flauna. </p>$SATQ$, false, 0, $SATQ$OSP-733-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$442af871-5705-4664-b3fe-9286d9b0ba1d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"13f36b03","external_id":"d97a955a-4eec-46ae-8d6f-3b584b6056d1","vaultid":"6b6128a8-a3aa-49d7-95af-e2b3c3ecf68f","uId":"cebc0710-f989-41f2-a982-f51ee2d461e1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Jon Ching is a Los Angeles-based painter.</li>\n<li>He uses the term &ldquo;flauna&rdquo; to describe the plant-animal hybrids that he depicts in his surreal paintings.</li>\n<li>&ldquo;Flauna&rdquo; is a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna.&rdquo;</li>\n<li>His painting <em>Nectar </em>depicts a parrot with leaves for feathers.</li>\n<li>His painting <em>Primaveral </em>depicts a snow leopard whose fur sprouts flowers.</li>\n</ul>","stem":"<p>The student wants to provide an explanation and example of &ldquo;flauna.&rdquo; Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"602bb841-876b-405a-8b4c-f7be25dee8ad","content":"<p>The term &ldquo;flauna,&rdquo; used by Los Angeles-based painter Jon Ching, is a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna.&rdquo;</p>"},{"id":"660bba88-af44-433c-85a4-b17b19516b8a","content":"<p>Jon Ching uses the term &ldquo;flauna,&rdquo; a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna,&rdquo; to describe the subjects of his surreal paintings: plant-animal hybrids such as a parrot with leaves for feathers.</p>"},{"id":"1d2bb99e-859d-4a55-b916-661904c5469b","content":"<p>Jon Ching, who created <em>Nectar</em>, refers to the subjects of his paintings as &ldquo;flauna.&rdquo;</p>"},{"id":"c48f409d-ba9d-43cc-9833-6ce2ff362008","content":"<p>The subjects of <em>Nectar </em>and <em>Primaveral </em>are types of &ldquo;flauna,&rdquo; a term that the paintings&rsquo; creator, Jon Ching, uses when describing his surreal artworks.</p>"}],"keys":["660bba88-af44-433c-85a4-b17b19516b8a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it provides both an explanation and an example of &ldquo;flauna.&rdquo; The sentence explains that flauna, a combination of the words &ldquo;flora&rdquo; and &ldquo;fauna,&rdquo; is a term used by Jon Ching to describe the plant-animal hybrids in his paintings. The sentence also mentions an example of Ching&rsquo;s flauna: a parrot with leaves for feathers.&nbsp;</p><p>Choice A is incorrect. While the sentence partially explains what &ldquo;flauna&rdquo; is, it doesn&rsquo;t provide a full explanation or specific example of Ching&rsquo;s flauna. Choice C is incorrect. While the sentence partially explains what &ldquo;flauna&rdquo; is and includes a title of a Ching painting, it doesn&rsquo;t provide a full explanation or specific example of Ching&rsquo;s flauna. Choice D is incorrect. While the sentence partially explains what &ldquo;flauna&rdquo; is and includes the titles of two Ching paintings, it doesn&rsquo;t provide a full explanation of Ching&rsquo;s flauna. </p>","parenttemplatename":"OSP-733-SYN","parenttemplateid":"","templateclusterid":"442af871-5705-4664-b3fe-9286d9b0ba1d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349)
